'use strict';
/* ---------- пояснення простими словами ----------
   id питання → [простими словами, як запам’ятати]. Показуються після помилки (див. feedbackHtml в app.js).
   check-questions.mjs перевіряє: є до кожного питання, без нових чисел і посилань на пункти. */
window.EXPLAIN={
"t1":["Обгін — це коли, щоб об’їхати когось попереду, виїжджаєш на зустрічну смугу. Якщо обганяєш, не залишаючи своїх смуг, — це просто випередження.","Обгін = заїзд на чужу половину дороги. Немає зустрічки — немає обгону."],
"t2":["Зупинка — це коротко: до 5 хвилин. Довше можна, лише коли саджаєш чи висаджуєш людей, вантажиш або виконуєш вимоги ПДР, інакше це вже стоянка.","Зупинка — до п’яти хвилин, стоянка — надовше. Понад 5 хвилин без причини = стоянка."],
"t3":["Недостатня видимість — це коли через сутінки, туман, дощ чи сніг бачиш дорогу менш ніж на 300 метрів. Якщо огляд закриває поворот чи пагорб, це вже обмежена оглядовість.","Недостатня видимість — винні погода чи сутінки, межа 300 м. Заважає поворот — це оглядовість."],
"t4":["Виїзд із двору, парковки чи АЗС — не перехрестя, а виїзд із прилеглої території. Тому, виїжджаючи, ти пропускаєш усіх: і пішоходів, і машини на дорозі.","З двору виїжджаєш — усім поступаєшся: двір не перехрестя."],
"t5":["Перехрестя починається не зі стоп-лінії й не зі знаків, а там, де край дороги починає заокруглюватися. Межа — уявна лінія між початками цих заокруглень.","Де край дороги «заокруглюється» — там і перехрестя починається."],
"t6":["Темна пора доби — весь час від заходу сонця до його сходу. Тож вечірні й ранкові сутінки теж рахуються темною порою.","Сонце сіло — темна пора почалася, сонце зійшло — закінчилася."],
"t7":["Водій — не лише той, хто тримає кермо. Інструктор, який навчає їзди, сидячи в цій самій машині, за ПДР теж водій.","Інструктор поруч — теж водій: у навчальному авто «водіїв» двоє."],
"t8":["Щоб смуга вважалася смугою руху, її ширина має бути щонайменше 2,75 м — з розміткою чи без неї.","Мінімум для смуги — 2,75 м: трохи менше трьох метрів."],
"t9":["В Україні машини їздять правою стороною дороги — рух правосторонній на всіх дорогах.","Правий — значить правильний: в Україні тримайся правого боку."],
"t10":["Якщо з твого причепа щось висипалося, прибирати маєш ти. Не виходить — попередь інших водіїв і повідом поліцію або власника дороги.","Хто насмітив на дорозі — той і прибирає, а не може — попереджає й кличе поліцію."],
"t11":["Велосипедисти, люди в кріслах колісних і пішоходи найменш захищені, тож водій має бути з ними особливо уважним.","Хто без металевого кузова — тому найбільше уваги: пішохід, велосипедист, крісло колісне."],
"t12":["Якщо разом із водієм у машині до дев’яти сидячих місць, це легковий автомобіль. Автобусом вона стає, коли місць більше дев’яти.","До 9 місць з водієм — легковик, з десятого — вже автобус."],
"t13":["Мікроавтобус — це невеликий одноповерховий автобус: у ньому не більше 17 сидячих місць разом із водійським.","Мікро — значить малий: до 17 місць разом із водієм."],
"t14":["Головна ознака автомагістралі — кожен напрямок має свою окрему проїжджу частину, а між ними — розділювальна смуга. Кількість смуг чи освітлення тут не вирішують.","Автомагістраль — дві окремі дороги «туди» і «назад», розділені смугою посередині."],
"t15":["Дорога — це те, що спеціально облаштоване для руху, разом із мостами й тимчасовими об’їздами. Колія, яку просто накатали через поле, дорогою не вважається.","Накатали — не будували: колія в полі — не дорога."],
"t16":["Автопоїзд — це авто-тягач, до якого зчіпним пристроєм приєднано один або кілька причепів. Авто на тросі — це вже буксирування, а не автопоїзд.","Автопоїзд як потяг: «локомотив» плюс «вагони»-причепи на зчіпці."],
"t17":["Безпечна дистанція — така відстань, за якої, якщо машина попереду різко загальмує, ти просто гальмуєш і не врізаєшся, нікуди не звертаючи й не об’їжджаючи.","Дистанція правильна, якщо рятує саме гальмо, а не кермо."],
"t18":["Інтервал — це відстань збоку: між твоєю машиною і сусідньою чи іншим об’єктом поруч. Дистанція — це відстань до машини попереду.","Інтервал — збоку, дистанція — спереду."],
"t19":["Безпечна швидкість — не число зі знака, а та, за якої ти контролюєш машину в конкретних умовах. У тумані чи на льоду вона може бути значно нижчою за дозволену.","Дозволена — на знаку, безпечна — за вікном: дивись на умови."],
"t20":["Якщо причіп правильно підібраний, має страхове з’єднання і спільну сигналізацію з тягачем, — це звичайна їзда автопоїздом, а не буксирування.","Причіп на зчіпці — це автопоїзд; буксирують, коли одне авто тягне інше."],
"t21":["Вимушена зупинка — коли далі їхати не можна: зламалася машина чи небезпеку створює вантаж. Висадити пасажира чи відповісти на дзвінок — це твій вибір, а не вимушена зупинка.","Вимушена — коли «змусили» поломка чи вантаж, а не твоє бажання."],
"t22":["Гальмовий шлях рахують від миті, коли ти починаєш тиснути на гальмо, і до повної зупинки. Час, поки помічаєш небезпеку й реагуєш, сюди не входить.","Гальмовий шлях — від гальма до зупинки. Немає натиску на гальмо — немає й гальмового шляху."],
"t23":["Дорога з покриттям (тут — асфальт) завжди головна відносно ґрунтової, навіть якщо знаків пріоритету немає.","Асфальт старший за ґрунтовку: хто з ґрунтової — той пропускає."],
"t24":["Острівець безпеки — піднятий над дорогою майданчик посеред пішохідного переходу, де пішохід може зупинитися й перечекати машини.","Острівець — як острів посеред річки машин: пішохід там перечікує."],
"t25":["Дати дорогу — не рушати, не їхати й не маневрувати так, щоб тому, хто має перевагу, довелося гальмувати чи змінювати напрямок. Якщо йому не заважаєш — можна їхати.","Дати дорогу = щоб іншому не довелося через тебе ні гальмувати, ні звертати."],
"t26":["Денні ходові вогні — білі фари спереду, що світять удень, аби твою машину було краще видно. Для темряви вони не призначені.","Денні — бо для дня: білі, спереду, щоб тебе помічали."],
"t27":["ДТП — будь-яка подія під час руху машини, через яку люди загинули, поранені або є матеріальні збитки. Навіть пом’ятий бампер без постраждалих — уже ДТП.","Є збитки — є ДТП, навіть якщо всі цілі й здорові."],
"t28":["Дорожні умови — це сама дорога: її стан, ширина, видимість, ухили. Обстановка — ті самі умови плюс перешкоди й те, скільки машин навколо.","Обстановка = умови + перешкоди + потік машин."],
"t29":["Шляхопровід піднімає одну дорогу над іншою і дає змогу з’їхати на іншу дорогу. Естакада теж підіймає дорогу, але з’їзду на іншу дорогу не має.","Шляхопровід «проводить» на іншу дорогу, естакада — ні, з неї не з’їдеш."],
"t30":["Двір — це житлова зона за самим визначенням, навіть без знака. Знаком же позначають житлову зону в інших частинах міста.","Двір = житлова зона завжди, зі знаком чи без."],
"t31":["Залишення місця ДТП — це коли учасник їде, щоб приховати пригоду чи її обставини, і поліції доводиться його шукати. Сам від’їзд, наприклад щоб відвезти потерпілого до лікарні, — ще не те саме.","Залишення місця ДТП = ховатися так, що поліції доводиться шукати."],
"t32":["Колона — це щонайменше три машини, які організовано їдуть одна за одною в одному напрямку з увімкненим ближнім світлом.","Двоє — це пара, а з трьох починається колона."],
"t33":["Крайнє праве положення — коли ти так близько до краю дороги, що між тобою і краєм не проїде навіть велосипед чи мотоцикл.","Крайнє праве — коли праворуч від тебе не протиснеться навіть двоколісний."],
"t34":["Маневр — це рушання з місця, перестроювання, поворот, розворот, з’їзд з дороги чи рух заднім ходом. Тож почати їхати зі стоянки — теж маневр.","Рушаєш з місця — вже маневруєш."],
"t35":["Маршрутний транспорт їздить сталим маршрутом і бере пасажирів у визначених місцях. Екскурсійний автобус без маршруту й зупинок до нього не належить.","Маршрутний — бо має маршрут. Немає маршруту — немає й «маршрутки»."],
"t36":["Транспорт з електромотором за ПДР рахується механічним, коли потужність мотора понад 3 кВт.","Поріг — три кіловати: понад 3 кВт на електриці — уже механічний ТЗ."],
"t37":["Межі мосту — початок і кінець його прольоту, тобто самої конструкції над перешкодою, а не перила чи знаки з назвою річки.","Міст там, де проліт: почався проліт — почався міст."],
"t38":["Триколісний транспорт з мотором і дозволеною масою не більше 400 кг прирівнюють до мотоциклів. 350 кг менше за цей поріг, тож це «мотоцикл».","Три колеса й до 400 кг — це ще мотоцикл, а не машина."],
"t39":["Межі населеного пункту позначають знаки на в’їзді й виїзді. Перші будинки чи межі громади на карті тут не важать — орієнтуйся на знаки.","Місто починається зі знака, а не з першої хати."],
"t40":["Якщо у твоїй смузі назустріч тобі їде інша машина, ПДР називають це небезпекою для руху, а не перешкодою.","Лоб у лоб у твоїй смузі = небезпека для руху."],
"t41":["Коли огляд закриває якийсь предмет — машина, будинок чи поворот, — це обмежена оглядовість. Недостатня видимість буває через погоду чи сутінки.","Заважає предмет — оглядовість; заважає погода — видимість."],
"t42":["Якщо в групі 30 дітей і більше, крім керівника з ними обов’язково їде ще й медичний працівник. Тут 32 дитини, тож потрібні обидва.","Від 30 дітей — керівник плюс медик."],
"t43":["Якщо на перехресті немає ні розмітки, ні знаків, ні світлофорів для пішоходів, перехід там усе одно є — завширшки як тротуари чи узбіччя.","Тротуар продовжується через дорогу — ось тобі й перехід."],
"t44":["Миготливий жовтий нічого не регулює, тож такий перехід вважається нерегульованим — так само, як без світлофора чи з вимкненим.","Блимає жовтий — світлофор «спить», перехід нерегульований."],
"t45":["Рейковий транспорт — це лише трамвай і техніка на трамвайних коліях. Тролейбус їздить на колесах по дорозі, тож він нерейковий, хоч і тримається за дроти.","Немає рейок під колесами — нерейковий, навіть із «рогами» до дротів."],
"t46":["Черговий на залізничному переїзді з посвідченням, пов’язкою, жезлом і у формі — такий самий регулювальник, і його сигнали треба виконувати.","Черговий на переїзді з жезлом і у формі = регулювальник."],
"t47":["Для поїздки за кордон літери на номерному знаку мають бути латинськими, а на машині — розпізнавальний знак держави, щоб її впізнавали в інших країнах.","За кордоном читають латиницю: латинські літери на номері й знак країни на авто."],
"t48":["Іноземне авто, яке перебуває в Україні більше двох місяців, за загальним правилом треба тимчасово зареєструвати.","Гостює понад два місяці — час реєструватися."],
"t49":["Якщо в колоні більше п’яти механічних ТЗ, умови й порядок її руху треба наперед погодити з поліцією.","Більше п’яти машин у колоні — спершу погодь із поліцією."],
"t50":["Переносити чи відновлювати номер кузова без погодження з сервісним центром МВС не можна навіть на спеціалізованій СТО і навіть якщо старий номер з’їла корозія.","Номер кузова — як паспорт авто: чіпати лише з погодження МВС."],
"d1":["У дорозі завжди май при собі три документи: посвідчення водія, реєстраційний документ на авто й поліс автоцивілки. Можна паперові, а можна в Дії.","Водій, машина, страховка — по документу на кожного: посвідчення, техпаспорт, поліс."],
"d2":["За ПДР водій сп’янілий, якщо в крові понад 0,2 проміле. Але навіть мала доза сповільнює реакцію, тож найкраще — не пити зовсім.","Межа 0,2 ‰ — це майже нуль. Правило просте: алкоголь і кермо не поєднуються."],
"d3":["Тримати телефон у руці під час руху не можна за будь-якої швидкості й будь-де. Говорити можна лише через гарнітуру чи гучний зв’язок.","Руки — для керма, а для розмови — гарнітура."],
"d4":["Після ДТП з потерпілими — зупинись, увімкни аварійку, постав знак, допоможи людям і виклич швидку й поліцію. Машину не відганяй і з місця не їдь.","Стоп, аварійка, знак, допомога, дзвінок — і нічого не зрушуй."],
"d5":["Якщо в машині є ремені безпеки, пристібатися мусять усі — і спереду, і ззаду. Водій не має права везти непристебнутих пасажирів.","Є ремінь — пристебнись, хоч спереду, хоч ззаду."],
"d6":["Дитину зростом менше 150 см возять лише в автокріслі чи бустері, пристебнутою ременем. На руках у дорослого чи просто ременем — не можна.","Нижча за 150 см — сідає в автокрісло чи на бустер."],
"d7":["Якщо хилить на сон, зупинись у дозволеному місці й відпочинь. Відчинене вікно чи гучна музика втоми не знімають, а керувати у стані втоми ПДР забороняє.","Сон за кермом не переможеш вікном: хочеш спати — зупинись і відпочинь."],
"d8":["Передати кермо людині без посвідчення не можна, навіть якщо ти поруч і дорога порожня. Виняток — лише навчальна їзда з інструктором.","Немає посвідчення — немає керма. Виняток — інструктор поруч."],
"d9":["Якщо вантаж з твоєї машини перегородив дорогу й одразу прибрати не виходить, попередь інших водіїв і повідом поліцію або власника дороги.","Не вдається прибрати — попередь людей і поклич поліцію."],
"d10":["Окрім полісу автоцивілки від українського страховика, страховку можна підтвердити «Зеленою карткою» від іноземного страховика. КАСКО для цього не годиться.","Наш поліс або іноземна «Зелена картка» — інше не рахується."],
"d11":["Знак «Водій з інвалідністю» можна використовувати, лише маючи документ, що підтверджує інвалідність водія чи пасажира. Без документа — лише коли інвалідність очевидна.","Знак — на склі, документ — при собі."],
"d12":["На місці для водіїв з малими дітьми можна стати лише з розпізнавальним знаком на авто та документом про вік дитини. Саме крісло в салоні не рахується.","Знак плюс документ — і місце твоє. Одне без іншого не працює."],
"d13":["Передати машину подрузі можна, якщо в неї є посвідчення потрібної категорії, — і разом з авто треба віддати їй реєстраційний документ.","Віддаєш ключі — віддай і техпаспорт, а в неї має бути посвідчення."],
"d14":["Перед поїздкою перевір, чи справна машина, чи все в ній на місці й чи надійно закріплений вантаж.","Перш ніж рушати — огляд: машина, комплект, вантаж."],
"d15":["Інструктор теж вважається водієм, тож пристібатися мусить, як і всі. Окремого винятку для інструкторів ПДР не мають.","Інструктор = водій, а водій пристібається."],
"d16":["У населеному пункті не пристібатися можна людям з інвалідністю, яким фізично неможливо пристебнутися, а також в оперативних і спеціальних машинах. Таксистам винятку немає.","Виняток — коли пристебнутися неможливо через здоров’я, а не коли незручно."],
"d17":["На мопеді, як і на мотоциклі, шолом обов’язковий для обох — і для тебе, і для пасажира, — і він має бути застебнутий.","Двоє на мопеді — два застебнуті шоломи."],
"d18":["Якщо хтось залишив на дорозі щось, що заважає руху, повідом про це дорожню службу або поліцію. Перекривати дорогу своєю машиною не треба.","Побачиш перешкоду — не проїжджай мовчки: повідом дорожників чи поліцію."],
"d19":["Нічого не можна викидати з машини на дорогу чи узбіччя — навіть недопалок чи огризок, і ні в місті, ні за містом. Це стосується і водія, і пасажирів.","Сміття — в пакет, а не за вікно: дорога — не смітник."],
"d20":["Окрім документів, на вимогу поліцейського ти маєш дати перевірити номери агрегатів і комплектність машини. Телефон і сумка до цієї перевірки не належать.","Перевіряють авто: документи, номери агрегатів, комплектність."],
"d21":["У прикордонній смузі прикордонник має право тебе зупинити: покажи реєстраційний документ на машину й дай її оглянути.","Біля кордону прикордонник перевіряє: техпаспорт і огляд авто."],
"d22":["Якщо поліцейський вимагає пройти огляд на сп’яніння, відмовитися не можна, навіть коли почуваєшся тверезо. Огляд проходять у встановленому порядку.","Почуваєшся тверезо — однаково проходиш огляд."],
"d23":["Позачерговий медогляд потрібен, щоб з’ясувати, чи може водій безпечно керувати машиною. Знання ПДР чи заміна посвідчення тут ні до чого.","Медогляд перевіряє здоров’я, а не знання: чи безпечно тобі кермувати."],
"d24":["Якщо медик просить твою машину, щоб довезти людину, якій потрібна екстрена допомога, до найближчої лікарні, — ти маєш її надати. Витрати потім можна відшкодувати.","Життя людини важливіше за твою поїздку: даєш авто, щоб довезти до лікарні."],
"d25":["Не зобов’язані надавати свою машину водії авто дипломатичних та інших іноземних представництв, міжнародних організацій, а також оперативних і спецмашин. Таксистам винятку немає.","Дипломатичну машину не «позичають» навіть для невідкладних потреб."],
"d26":["Якщо машину пошкоджено через погану дорогу — вибоїну, що не відповідає вимогам безпеки, — власник має право вимагати відшкодування збитків.","Вибоїна зламала — маєш право на компенсацію збитків."],
"d27":["Водій з інвалідністю і відповідним знаком на авто може не виконувати вимогу «Стоянку заборонено». А от на «В’їзд заборонено» чи «Проїзд без зупинки заборонено» пільга не поширюється.","Пільга — на стоянку, а не на в’їзд."],
"d28":["Якщо ліки знижують увагу чи реакцію, кермувати не можна, навіть якщо їх призначив лікар і ти збираєшся їхати повільно.","Ліки гальмують реакцію — значить, машина стоїть."],
"d29":["Коли ти хворієш — висока температура, слабкість, — за кермо сідати не можна, навіть на коротку поїздку.","Температура — це ліжко, а не кермо."],
"d30":["Номер має чітко читатися з 20 метрів. Якщо з такої відстані символи не розібрати, він вважається закритим чи брудним.","Номер — для читання: з 20 м усе має бути видно чітко."],
"d31":["Передавати кермо людині напідпитку не можна, навіть якщо в неї є посвідчення і вона каже, що почувається нормально.","Хто напідпитку — тому ключів не даєш, хоч би що казав."],
"d32":["Кермо можна передати лише тому, хто має посвідчення при собі — паперове чи в Дії. Назвати номер по пам’яті не досить.","Немає посвідчення в кишені чи в телефоні — немає керма."],
"d33":["Тримати телефон у руці під час руху можна лише водіям оперативних машин, коли вони виконують невідкладне службове завдання. Іншим — ні, навіть таксистам.","Телефон у руці — лише в оперативної служби на терміновому завданні."],
"d34":["Якщо потерпілого до лікарні везеш ти, перед від’їздом зафіксуй сліди пригоди й те, де стоїть твоє авто. Потім треба повернутися на місце.","Спершу закарбуй місце: сліди й положення авто — і лише тоді в дорогу."],
"d35":["Після ДТП запиши прізвища й адреси свідків, щоб потім їх можна було знайти. Проганяти їх не треба.","Очевидці — твої помічники: запиши, хто вони й де живуть."],
"d36":["Після ДТП, поки не пройдено медогляд, не можна вживати алкоголь, наркотики й ліки на їх основі без призначення медика.","Після аварії — ані краплі, доки не буде медогляду."],
"d37":["Якщо ніхто не постраждав, шкоди іншим немає, машини на ходу, а водії згодні щодо обставин, — складіть і підпишіть схему й самі їдьте до найближчого поста чи відділку поліції.","Без жертв і суперечок — схема, підписи й до поліції своїм ходом."],
"d38":["Без поліції можна оформити ДТП, коли зіткнулися лише два застраховані авто, шкоди завдано тільки їм, ніхто не постраждав, а водії тверезі й згодні щодо обставин.","Два авто, обидва застраховані, водії тверезі й згодні — тоді поліцію не кличуть."],
"d39":["Право керувати легковиком (категорія B) дають з 18 років — з повноліття.","B — з повноліття: 18 років, і за кермо легковика."],
"d40":["У машині категорії B може бути не більше восьми сидячих місць, не рахуючи водійського. Разом із водієм — дев’ять.","Вісім пасажирів + водій = дев’ять: більше — це вже не B."],
"d41":["Якщо причіп важчий за 750 кг, звичайної категорії B мало — потрібна BE. З причепом до 750 кг вистачає B.","B плюс E — машина плюс важкий причіп понад 750 кг."],
"d42":["Право на мотоцикл чи мопед (категорії A1, A) дають з 16 років. З 14 можна лише навчатися їздити.","Мотоцикл — з 16, легковик — з 18: двоколісне раніше."],
"d43":["Коли поліцейський тебе зупиняє, ти маєш право знати причину зупинки, його прізвище й посаду, а також попросити показати посвідчення.","Три питання до поліцейського: чому зупинили, хто ви, яка посада."],
"d44":["Відступити від правил можна лише за непереборної сили або коли іншого способу врятувати людей від загибелі чи каліцтва немає. Поспіх чи порожня дорога — не причина.","Відступити від правил можна лише заради чийогось життя або через непереборну силу, а не через поспіх."],
"d45":["Таксі може їздити смугою для маршрутного транспорту й висаджувати там пасажирів, дотримуючись правил зупинки.","Смуга для маршруток відкрита й для таксі: їдь і висаджуй пасажирів."],
"d46":["Смугою для маршрутного транспорту можна їхати на мотоциклі й мопеді, але мотоцикл з боковим причепом, мотоколяски й триколісні ТЗ туди не пускають.","Два колеса — можна в смугу для маршруток, три (з коляскою) — ні."],
"d47":["Якщо немає ні майданчика, ні тротуару, ні узбіччя, пасажир виходить з боку крайньої смуги — а не з того боку, де їдуть машини сусідньої смуги.","Виходь до краю дороги, а не в потік."],
"d48":["Пасажирам не можна відчиняти двері, поки машина не зупинилася біля тротуару, краю дороги чи узбіччя.","Спершу зупинка, потім двері."],
"d49":["Пасажир теж має обов’язки після ДТП: допомогти потерпілим, повідомити поліцію й лишатися на місці до її приїзду.","Після ДТП пасажир — не глядач: допомога, дзвінок, чекаємо поліцію."],
"d50":["Навчатися водіння можна лише тим, у кого немає медичних протипоказань, — і це має підтверджувати медична довідка.","Спершу лікар, потім кермо: без довідки — без навчання."],
"d51":["Вчитися кермувати автомобілем можна з 16 років, а мотоциклом чи мопедом — з 14. Учень має мати з собою документ про вік.","Вчитися — з 16, посвідчення на авто — з 18."],
"d52":["Перші уроки водіння проходять на закритому майданчику чи автодромі, або там, де немає інших учасників руху. На жваві вулиці виїжджають пізніше.","Спершу майданчик, потім вулиця: плавати вчаться в басейні, а не в морі."],
"d53":["Учень може виїжджати на дороги лише зі спеціалістом з підготовки водіїв і коли вже має достатні початкові навички.","На дорогу — з інструктором і з навичками, а не лише зі знаком на склі."],
"d54":["У навчальній машині для інструктора ставлять додаткову педаль гальма (і зчеплення, якщо воно є) та окреме дзеркало, щоб він міг вчасно втрутитися.","В інструктора своя педаль гальма й своє дзеркало — щоб зупинити й бачити."],
"d55":["Вчити кермувати заборонено в житловій зоні (наприклад, у дворах), на дорогах для автомобілів і на автомагістралях.","Двори та швидкісні траси — не для учнів."],
"g1":["Жовтий — це вже заборона: він попереджає, що зараз зміниться сигнал. Проїхати можна, лише якщо зупинитися вдасться тільки екстреним гальмуванням.","Жовтий — не «газуй», а «стій»: він лише попереджає про зміну."],
"g2":["Миготливий жовтий дозволяє їхати, але попереджає: попереду небезпечне перехрестя чи перехід без регулювання. Хто кого пропускає — дивись на знаки або на перешкоду справа.","Жовтий блимає — світлофор «відпочиває», а ти пильнуєш: діють знаки."],
"g3":["Миготливий зелений ще дозволяє їхати, але попереджає, що от-от загориться заборонний сигнал. Оціни, чи встигаєш, і готуйся зупинитися.","Зелений блимає — як таймер: час спливає."],
"g4":["Зелена стрілка праворуч при червоному дозволяє повернути, але ти маєш пропустити машини з інших напрямків — переваги вона не дає.","Стрілка при червоному — дозвіл, а не перевага: повертай, але пропускай."],
"g5":["Піднята вгору рука регулювальника забороняє рух усім і в усіх напрямках — як жовтий сигнал. Проїхати можна лише тому, хто не зупиниться без екстреного гальмування.","Рука вгору — як жовтий: усі стоять."],
"g6":["Коли регулювальник стоїть до тебе боком (руки опущені чи розведені), можна їхати прямо й праворуч. Трамваю — лише прямо.","Боком стоїть — пропускає: прямо і праворуч."],
"g7":["Якщо регулювальник стоїть до тебе грудьми, а права рука витягнута вперед, можна повернути лише праворуч.","Регулювальник до тебе грудьми — тільки праворуч."],
"g8":["Якщо світлофор і регулювальник показують різне, слухай регулювальника: його сигнали важливіші за світлофор і знаки.","Жива людина важливіша за лампочку."],
"g9":["Рухом керує все разом: знаки, розмітка, дорожнє обладнання, світлофори й регулювальники. Жодного з них не можна ігнорувати.","П’ять «регулювальників»: знак, розмітка, обладнання, світлофор і людина з жезлом."],
"g10":["Якщо знак і розмітка суперечать одне одному, головний — знак.","Знак стоїть вище за розмітку — і буквально, і за правилами."],
"g11":["Тимчасовий знак — на переносній стійці, обладнанні чи жовтому щиті — важливіший за постійний: він показує, що ситуація на дорозі змінилася.","Жовтий щит — свіжа новина: тимчасове сильніше за постійне."],
"g12":["Дорожній знак має бути видно щонайменше зі 100 метрів, щоб його можна було вчасно помітити.","Знак видно здалеку — щонайменше за 100 м."],
"g13":["Зазвичай світлофор важливіший за знаки пріоритету. Але коли блимає жовтий, перехрестя стає нерегульованим, і ти їдеш за знаками пріоритету.","Жовтий блимає — світлофор «віддав владу», командують знаки."],
"g14":["Регулювальник головніший за все: його вимоги виконують, навіть якщо вони суперечать знакам, розмітці чи світлофору.","Регулювальник — козир, що б’є і знаки, і розмітку."],
"g15":["Знаки пріоритету кажуть, хто проїжджає першим на перехресті чи вузькій ділянці. Куди їхати, вказують інші — наказові — знаки.","Пріоритет = черга: хто першим проїжджає."],
"g16":["Коли розмітка й знаки стоять разом, розмітка не скасовує знак, а підкреслює чи уточнює його вимоги.","Розмітка — як підкреслення в тексті: виділяє те, що каже знак."],
"g17":["Світлофори бувають зеленого, жовтого, червоного і біло-місячного кольору. Біло-місячні сигнали трапляються, наприклад, у трамвайних світлофорах і на залізничних переїздах.","Три звичні кольори плюс «місяць» — біло-місячний для трамваїв і переїздів."],
"g18":["У горизонтальному світлофорі червоний завжди зліва, зелений — справа. У вертикальному червоний — нагорі.","Читаєш зліва направо — спершу «стоп», потім «їдь»."],
"g19":["Додаткові секції зі стрілками у вертикальному світлофорі розташовані на рівні зеленого сигналу. На рівні червоного буває хіба біла табличка зі стрілкою.","Стрілка зелена — і сидить поруч із зеленим."],
"g20":["Якщо основний сигнал — зелена стрілка праворуч, їхати можна тільки праворуч. Прямо чи ліворуч — ні.","Стрілка показує один шлях — туди й їдь."],
"g21":["Зелена стрілка ліворуч дозволяє не лише поворот ліворуч, а й розворот, якщо знаки його не забороняють.","Де можна ліворуч — там можна й розвернутися, якщо знак не проти."],
"g22":["Коли разом з основним зеленим горить стрілка праворуч, ти повертаєш праворуч з перевагою перед машинами з інших напрямків.","Стрілка з зеленим — перевага, стрілка з червоним — поступись."],
"g23":["Табло біля світлофора показує, скільки секунд залишилося до кінця зеленого. Так легше вирішити, чи встигаєш проїхати.","Табло — зворотний відлік зеленого."],
"g24":["Чорна контурна стрілка на зеленому означає, що є ще й додаткова секція, а сама стрілка показує інші напрямки, куди можна їхати на цей зелений.","Контур на зеленому — «є ще секція, а ось куди можна вже зараз»."],
"g25":["Два жовті вогні, що блимають над переходом, дозволяють їхати, але попереджають: це небезпечний перехід без регулювання, тож пильнуй пішоходів.","Блимає жовтий — «увага, пішоходи», а не «стоп»."],
"g26":["Червоний — це заборона, навіть коли блимає. Рушати не можна, хоч би як порожньо було навколо.","Червоний є червоний — хоч світить, хоч блимає."],
"g27":["Біла табличка з зеленою стрілкою дозволяє повернути праворуч на червоний — але тільки з крайньої правої смуги й пропустивши всіх, хто їде чи йде на свій зелений.","Табличка — дозвіл «після всіх»: спершу пропусти тих, хто має зелений."],
"g28":["На дорозі з одностороннім рухом ліворуч на червоний за табличкою зі стрілкою повертають з крайньої лівої смуги, пропустивши інших.","Повертаєш ліворуч — і смугу береш ліву."],
"g29":["Червоний разом із жовтим ще забороняють рух — вони лише попереджають, що зараз загориться зелений. Рушай, коли засвітиться зелений.","Червоний + жовтий = «приготуйся», а не «їдь»."],
"g30":["Контурна стрілка на червоному не дозволяє їхати — вона лише підказує, куди можна буде рушити, коли загориться зелений.","Стрілка на червоному — анонс, а не дозвіл."],
"g31":["Якщо додаткова секція зі стрілкою не горить, у її напрямку їхати не можна — повертати праворуч на червоний заборонено.","Стрілка згасла — дорога туди закрита."],
"g32":["Червоний хрест над смугою означає, що їхати нею заборонено. Це реверсивний світлофор: зелена стрілка вниз, навпаки, дозволяє рух смугою.","Хрест — як «перекреслено»: смуга закрита."],
"g33":["Жовта стрілка вниз-праворуч над реверсивною смугою означає, що рух нею вже заборонено і треба перестроїтися на смугу праворуч.","Стрілка нахилена праворуч — і ти перестроюєшся праворуч."],
"g34":["Якщо реверсивний світлофор над смугою з розміткою 1.9 з обох боків вимкнений, заїжджати на неї не можна.","Світлофор мовчить — смуга закрита: немає дозволу — немає в’їзду."],
"g35":["Спеціальний світлофор для трамваїв може мати чотири біло-місячні вогні, розташовані літерою «Т».","«Т» — значить трамвай."],
"g36":["У трамвайному світлофорі рух дозволено лише тоді, коли горить нижній сигнал разом із верхнім. Якщо світяться лише три верхні — трамваю стояти.","Без нижнього вогника — ні руху: три верхні означають «стій»."],
"g37":["Нижній сигнал разом із верхнім дозволяє трамваю рух, і куди вказує верхній, туди й можна: горить правий — отже, праворуч.","Верхній вогник — як стрілка: правий світить — трамвай іде праворуч."],
"g38":["Біло-місячний вогник, що блимає на переїзді, означає: сигналізація працює справно і рух не заборонено. Рух забороняють миготливі червоні.","Біле блимає — шлях відкритий, червоне блимає — стій."],
"g39":["Світлофор із чоловічком керує лише пішоходами: зелений дозволяє їм іти, червоний забороняє. Водіям він нічого не вказує.","Чоловічок на світлофорі — для тих, хто ходить пішки, а не їздить."],
"g40":["Регулювальник «говорить» усім тілом: важить, як він стоїть до тебе, і що показує руками — з жезлом, диском або без них.","Читай регулювальника як знак: корпус + руки = сигнал."],
"g41":["Свисток нічого не дозволяє і не забороняє — регулювальник свистить, щоб усі звернули на нього увагу.","Свисток — це «Увага на мене!», а не команда їхати чи стояти."],
"g42":["Якщо регулювальник стоїть до тебе грудьми з руками в сторони, їхати не можна — так само, як і з боку його спини.","Груди чи спина регулювальника — для тебе стіна."],
"g43":["Коли регулювальник опустив руки, трамваю з його лівого чи правого боку можна лише прямо. Звичайним авто звідти — прямо і праворуч.","Боком до регулювальника: трамвай — тільки прямо, авто — прямо і праворуч."],
"g44":["Права рука, зігнута перед грудьми, означає те саме, що руки в сторони. Ти збоку від регулювальника, тож тобі можна прямо і праворуч.","Бачиш бік регулювальника — можна прямо й праворуч."],
"g45":["Коли руки регулювальника опущені, пішоходи можуть переходити дорогу в нього за спиною і перед грудьми.","Пішоходи йдуть повз груди і спину, авто їдуть з боків."],
"g46":["Права рука регулювальника витягнута вперед, а ти з його лівого боку — для тебе відкриті всі напрямки, їдь куди потрібно.","Зліва від регулювальника з рукою вперед — усі дороги твої."],
"g47":["У такій позиції регулювальника трамвай з його лівого боку може їхати тільки ліворуч, хоча звичайним авто звідти можна в усі боки.","Трамвай зліва — трамваю тільки ліворуч: ліво до ліва."],
"g48":["Права рука регулювальника витягнута вперед, а ти з його правого боку — стоїш. З правого боку і зі спини рух заборонено.","Стоїш справа чи за спиною регулювальника — їхати не маєш права."],
"g49":["Жезл у руках поліцейського — інструмент лише для керування рухом. Вимогу зупинитися конкретному авто подають іншими способами.","Жезл — як диригентська паличка: диригує потоком, а не зупиняє когось одного."],
"g50":["Регулювальник може показати й жест, якого немає в ПДР, якщо його зміст зрозумілий. Його сигнали обов’язкові, тож виконуй.","Жест зрозумілий — виконуй, навіть якщо його немає в підручнику."],
"g51":["Вимогу зупинитися подають не лише жезлом, а й маячком, сиреною чи гучномовцем. Зупиняєшся там, де вказали, але без порушення правил зупинки.","Поліція просить стати — стаєш де вказали, але за правилами, а не посеред смуги."],
"g52":["Якщо на поліцейському авто блимає синьо-червоний або лише червоний маячок, це може бути вимога зупинитися.","Є червоний на маячку — синьо-червоний чи суто червоний — готуйся зупинитися."],
"g53":["Немає стоп-лінії й знака «Місце зупинки» — зупиняйся перед світлофором або перед пішохідним переходом, щоб «зебра» лишалася вільною.","Зебра — для людей, а не для твоїх коліс: стій перед нею."],
"g54":["Жовтий спалахнув, а встигнути зупинитися можна лише різким гальмуванням? Тоді їдь далі, але обережно й безпечно.","Жовтий надто близько? Не бий по гальмах — спокійно й безпечно проїжджай."],
"g55":["Рекламу, яку можна сплутати зі знаком, ставити біля дороги заборонено — водій може прийняти її за справжній знак або відволіктися.","Знак має бути один-єдиний: жодних двійників у рекламі."],
"z1":["Трикутник вершиною донизу каже: пропусти тих, хто їде головною дорогою. Зупинятися не обов’язково, якщо нікому не заважаєш.","Перевернутий трикутник — «пропусти»: поступитися обов’язково, зупинитися — ні."],
"z2":["Знак «STOP» вимагає зупинитися завжди, навіть на порожній дорозі: біля стоп-лінії, а якщо її немає — біля знака. Потім пропусти тих, хто має перевагу.","STOP — це не «якщо», а «завжди»: спершу колеса стали, потім думаєш далі."],
"z3":["Жовтий ромб означає, що ти на головній дорозі. На перехрестях без світлофора й регулювальника ті, хто виїжджає з другорядних, мають тебе пропустити.","Жовтий ромб — як корона: на нерегульованому перехресті перевага твоя."],
"z4":["Перекреслений ромб означає, що головна дорога скінчилася і переваги в тебе вже немає. Далі черговість — за знаками або правилом «перешкода справа».","Ромб перекреслили — корону зняли."],
"z5":["Цей знак («цеглина») забороняє в’їзд усього транспорту саме в цьому напрямку. Його часто ставлять на виїзді з дороги з одностороннім рухом.","«Цеглина» перекриває в’їзд лише з твого боку, а не всю дорогу."],
"z6":["Цей знак забороняє рух усього транспорту дорогою взагалі, а не лише в’їзд з одного боку, як «цеглина».","Порожнє біле коло в червоній облямівці — порожня дорога: їздити не можна."],
"z7":["Обмеження швидкості діє до найближчого перехрестя за знаком, якщо раніше його не скасує знак кінця обмеження чи знак з іншим числом.","Знак швидкості живе до першого перехрестя."],
"z8":["Червоний хрест на синьому колі — тут не можна ні зупинитися, ні поставити авто на стоянку. Де заборонена зупинка, там і стоянка.","Хрест — двічі «ні»: ні зупинки, ні стоянки."],
"z9":["Одна червона смуга на синьому колі забороняє стоянку, а ненадовго зупинитися тут можна.","Одна смуга — одна заборона (стоянка), дві смуги хрестом — дві (зупинка і стоянка)."],
"z10":["Синє коло зі стрілкою — це наказ: на перехресті можна їхати лише прямо, повертати не можна.","Синє коло наказує, а не радить: стрілка прямо — їдеш тільки прямо."],
"z11":["Коли постійний і тимчасовий знак (на жовтому щиті чи переносній стійці) суперечать одне одному, слухайся тимчасового — він має перевагу.","Жовтий фон — свіжа новина: тимчасове важливіше за постійне."],
"z12":["Поза населеним пунктом знак «Небезпечний поворот» ставлять, коли радіус заокруглення менше 500 м. У населеному пункті поріг менший — 150 м.","Поза містом — 500, у місті — 150: за містом і число більше."],
"z13":["Знак «Крутий спуск» попереджає, що попереду діють правила руху гірськими дорогами і на крутих спусках.","Крутий спуск = маленька гора: їдь за правилами гірських доріг."],
"z14":["Знак «Виїзд на набережну або берег» з табличкою «Поромна переправа» попереджає: попереду берег, звідки йде пором.","Берег + табличка з поромом = попереду переправа, а не пляж."],
"z15":["Знак «Пагорб» ставлять і перед штучною нерівністю, «лежачим поліцейським», щоб змусити пригальмувати — наприклад, там, де дорогу часто переходять діти.","«Пагорб» буває й рукотворний — це «лежачий поліцейський»."],
"z16":["Трикутний знак «Пішохідний перехід» попереджає, що попереду нерегульований перехід — без світлофора, позначений знаками або розміткою.","Трикутник — попередження: попереду «зебра» без світлофора."],
"z17":["У населених пунктах із попереджувальних знаків повторюють лише два: «Діти» та «Дорожні роботи».","Діти і ремонт — про них нагадують двічі навіть у місті."],
"z18":["Якщо дорожні роботи короткочасні, знак «Дорожні роботи» в населеному пункті можна поставити зовсім близько — за 10–15 м, а не як зазвичай за 50–100 м.","Короткі роботи — короткий відступ: 10–15 м."],
"z19":["«Вибоїна» — тимчасовий знак: його ставлять на той час, поки на дорозі тривають роботи.","Вибоїну залатають — і знак заберуть."],
"z20":["Знак 1.41 позначає місце, де часто стаються ДТП, а таблички під ним підказують, яка саме пригода тут можлива.","Знак — «тут часто аварії», табличка — «які саме»."],
"z21":["Знак зі знаком оклику попереджає про аварійно небезпечну ділянку: дорога там не відповідає будівельним нормам, тож пильнуй.","Знак оклику — «обережно, з дорогою тут щось не так»."],
"z22":["Табличка «Лижники» під знаком небезпеки означає, що поруч гірськолижні траси або траси для інших зимових видів спорту.","Лижник на табличці — поруч зимові траси, а не туристичні стежки."],
"z23":["Цей знак попереджає про перехрестя рівнозначних доріг: головної тут немає, тож поступаєшся тим, хто наближається справа.","Дороги рівні — хто справа, той перший."],
"z24":["Поза населеним пунктом попереджувальні знаки ставлять за 150–300 м до небезпечного місця, у населеному — за 50–100 м.","За містом — 150–300 м, у місті — 50–100 м: їдеш швидше — попереджають раніше."],
"z25":["Цей знак попереджає, що попереду світлофор: на перехресті, пішохідному переході чи іншій ділянці дороги.","Світлофор намальований на знаку — справжній чекає попереду."],
"z26":["Знак «Одноколійна залізниця» позначає переїзд без шлагбаума, і його ставлять безпосередньо перед самим переїздом.","Хрест переїзду стоїть біля самих рейок, а не за сотні метрів до них."],
"z27":["Подвійний червоно-білий хрест — переїзд без шлагбаума, де колій дві або більше.","Один хрест — одна колія, подвійний хрест — колій багато."],
"z28":["Табличка показує, куди йде головна дорога. Пропускаєш тих, хто їде нею, навіть якщо на перехресті вона повертає.","Жирна лінія на табличці — головна: хто їде по ній, той і перший."],
"z29":["Табличка «300 м» під знаком «Дати дорогу» означає: через 300 метрів буде перехрестя, де доведеться пропустити інших.","Табличка з відстанню — це «скоро», а не «тут»: поступишся через 300 м."],
"z30":["Знак «STOP» перед переїздом вимагає зупинитися завжди, навіть якщо потяга не видно. Немає стоп-лінії — зупиняйся перед самим знаком.","Потяга не видно — не привід: STOP є STOP."],
"z31":["Щоб знак «STOP» перед перехрестям не став несподіванкою, заздалегідь ставлять «Дати дорогу» з табличкою відстані.","Спершу «Дати дорогу» з відстанню — як анонс, потім STOP."],
"z32":["Жирна лінія на табличці під «Головною дорогою» — це і є головна дорога. Вона повертає ліворуч, отже, і головна на перехресті йде ліворуч.","Жирна лінія = головна дорога: куди вона, туди й перевага."],
"z33":["Знак «Перевага зустрічного руху» означає, що зустрічні тут мають перевагу. Зустрічне авто вже на вузькій ділянці — чекай, поки проїде, і тоді їдь.","Вузька ділянка — як вузькі двері: хто вже зайшов, того й пропусти."],
"z34":["Знак «Перевага перед зустрічним рухом» означає, що на вузькій ділянці перевага в тебе, а зустрічні мають пропустити.","2.5 — ти поступаєшся, 2.6 — поступаються тобі."],
"z35":["Знак «Рух заборонено» не діє на маршрутний транспорт, а також на водіїв з інвалідністю й авто тих, хто живе чи працює в цій зоні.","Маршрутка їде своїм маршрутом — і цей знак його не перекриває."],
"z36":["Якщо живеш у такій зоні, заїхати додому можна, але в’їжджати й виїжджати треба на найближчому до дому перехресті, а не кататися зоною.","Додому можна, але найкоротшим шляхом — через найближче перехрестя."],
"z37":["Якщо маси на знаку немає, заборона стосується вантажівок і составів з дозволеною максимальною масою понад 3,5 т, а також тракторів.","Немає цифри на знаку — діє стандартний поріг 3,5 т, плюс трактори."],
"z38":["Вантажівки зі скісною білою смугою на боці або ті, що везуть групи людей, під дію цього знака не підпадають.","Біла смуга навскіс на боці — перепустка під цей знак."],
"z39":["Знак «Рух з причепом заборонено» стосується вантажівок і тракторів. На легковику з причепом їхати далі можна.","Знак з причепом — про вантажівки й трактори, а не про легковик з дачним причепом."],
"z40":["Цей знак забороняє не лише причепи для вантажівок і тракторів, а й буксирування будь-якого механічного транспорту, тож тягнути зламане авто тут не можна.","Буксир — теж «причіп»: під цим знаком буксирувати не можна."],
"z41":["Знак забороняє їздити на мопедах і на велосипедах з підвісним двигуном. Для мотоциклів є окремий знак.","Велосипед із моторчиком — майже мопед, тож і заборона та сама."],
"z42":["Тут рахують реальну масу авто разом із причепом — скільки воно важить зараз, а не цифру з документів.","Знак зважує, як ваги: скільки є зараз, а не скільки в документах."],
"z43":["Знак обмеження висоти враховує висоту разом із вантажем. З вантажем твоя вантажівка вища, ніж дозволяє знак, тож треба об’їхати іншим маршрутом.","З вантажем вище за знак — під міст не пхайся, шукай об’їзд."],
"z44":["Знак із числом «70 м» вимагає тримати відстань до машини попереду не менше 70 м.","Метри на знаку — мінімальна дистанція до передньої машини."],
"z45":["«Цеглина» з табличкою «Смуга руху» над смугою забороняє в’їзд лише на цю смугу, а сусідніми їхати можна.","Знак над смугою — заборона лише для цієї смуги."],
"z46":["На АЗС «цеглину» ставлять, щоб розділити в’їзд і виїзд: цим проїздом можна тільки виїхати, а заїжджати — іншим.","Один проїзд — для в’їзду, інший — для виїзду: «цеглина» стоїть на виїзді."],
"z47":["Знак «Поворот праворуч заборонено» діє не лише на перехрестях, а й перед будь-яким місцем, де його поставили, наприклад перед в’їздом на АЗС.","Де стоїть знак, там і заборона — перехрестя не обов’язкове."],
"z48":["Знак забороняє тільки поворот ліворуч. Розвернутися на цьому перехресті можна.","Заборонили «ліворуч», а не «розворот» — розвертатися можна."],
"z49":["Знак забороняє лише розворот. Повернути ліворуч на цьому перехресті можна.","Перекреслена «підкова» — під забороною тільки розворот, ліворуч можна."],
"z50":["Під цим знаком обганяти не можна нікого, окрім поодинокого транспорту, що їде повільніше 30 км/год.","Хто сам і ледве повзе — менше 30 км/год, — того обігнати можна."],
"z51":["«Поодинокий» — це не лише одна машина: це й автопоїзд, і буксир разом із тим, кого він тягне.","Поодинокий = одна «зв’язка»: машина, автопоїзд чи буксир з буксированим."],
"z52":["Цей знак позначає кінець зони «Обгін заборонено»: з цього місця обганяти знову можна. Інші заборони він не скасовує.","Кінець «Обгін заборонено» знімає тільки заборону обгону, а не всі інші."],
"z53":["Трактору під цим знаком можна обігнати лише поодинокий велосипед чи гужовий віз (сани), а будь-яку машину — ні.","Трактор обганяє тільки тих, хто без мотора: велосипед і коня."],
"z54":["Якщо обмеження стоїть перед населеним пунктом і перехресть до в’їзду немає, воно діє лише до знака початку населеного пункту.","Знак швидкості перед селом «здає зміну» знаку з назвою населеного пункту."],
"z55":["Табличка «Ожеледиця» означає, що обмеження діє лише взимку, коли дорога може бути слизькою.","Ожеледиця буває взимку — тоді й діє знак."],
"z56":["Перекреслене число 50 означає кінець зони, де діяло обмеження швидкості 50 км/год. Це не порада і не мінімальна швидкість.","Число перекреслене — обмеження скінчилося, а не стало порадою чи мінімумом."],
"z57":["Знак «Зона обмеження максимальної швидкості» діє на всю зону — на всіх вулицях мікрорайону, аж до знака кінця зони, а не до перехрестя.","Зона — як парасолька: накриває всі вулиці, поки не побачиш знак її кінця."],
"z58":["Під цим знаком сигналити не можна. Виняток один — коли інакше не вдасться запобігти аварії.","Клаксон тут — лише рятувальний круг від ДТП."],
"z59":["Під знаком «Зупинку заборонено» може ненадовго стати лише таксі — щоб посадити чи висадити пасажирів або завантажити чи вивантажити речі.","Таксі — виняток: швидко взяти чи висадити пасажира й їхати далі."],
"z60":["Водію з інвалідністю можна зупинитися під цим знаком, тільки якщо під ним є табличка «Крім осіб з інвалідністю». Без неї заборона діє для всіх.","Є табличка «Крім осіб з інвалідністю» — можна, немає таблички — ні."],
"z61":["Знак «Стоянку заборонено» не діє на таксі з увімкненим таксометром, а також на водіїв з інвалідністю з розпізнавальним знаком.","Лічильник цокає — таксі на роботі, тож стояти можна."],
"z62":["Знаки заборони зупинки чи стоянки діють тільки на тому боці дороги, де їх поставили. На протилежному боці вони не діють.","Знак стоянки бачить лише свій бік вулиці."],
"z63":["Коли на вулиці діють обидва знаки — для непарних і парних чисел, — авто переставляють на інший бік увечері, з 19 до 24 год.","Вечір від 19 до 24 — час перегнати авто на інший бік."],
"z64":["Табличка 7.2.4 нагадує, що ти все ще в зоні дії знака і заборона триває. Кінець зони позначає інша табличка.","Табличка-нагадування: «ти ще в зоні», а не «зона скінчилася»."],
"z65":["Табличка «Евакуатор» попереджає: якщо залишиш тут авто, його можуть евакуювати без твого відома.","Намальований евакуатор — твоє авто може поїхати без тебе."],
"z66":["У зоні обмеженої стоянки головне — час: стояти можна обмежено довго, і байдуже, платна стоянка чи ні. Умови пишуть на знаку або табличках.","Обмежена стоянка — про годинник, а не про гаманець."],
"z67":["Знак «Контроль» означає, що попереду контрольний пункт — наприклад, пункт оплати проїзду чи пост поліції, — і проїхати його без зупинки не можна.","«Контроль» — як каса на виїзді: спершу зупинка, потім далі."],
"z68":["Цей знак знімає заборони й обмеження, що діяли до нього: обгону, швидкості, зупинки, стоянки тощо. Наказові знаки та знаки пріоритету він не скасовує.","Кінець заборон — це кінець «не можна», а не кінець «треба» і «головна»."],
"z69":["Знак «Небезпека» забороняє рух абсолютно всім — і машинам, і пішоходам, бо попереду аварія, стихійне лихо чи інша небезпека.","«Небезпека» — це «стоп» для всіх, навіть для тих, хто пішки."],
"z70":["Виїзд з АЗС чи двору — це не перехрестя доріг, тож дія знака на ньому не закінчується.","Виїзд з АЗС — не перехрестя: знак працює далі."],
"z71":["Знак «Рух прямо» за перехрестям діє до наступного перехрестя, але звернути праворуч у двір чи на іншу прилеглу територію не забороняє.","«Прямо» — про перехрестя, а праворуч у двір можна."],
"z72":["Знак «Рух праворуч» дозволяє лише поворот праворуч. Розвертатися тут не можна.","Розворот дозволяють знаки зі стрілкою ліворуч, а тут її немає — тільки праворуч."],
"z73":["Знак «Рух ліворуч» дозволяє повернути ліворуч, а також розвернутися.","Синя стрілка ліворуч — це і поворот, і розворот."],
"z74":["Наказові знаки зі стрілками напрямку не діють на маршрутний транспорт, тож автобус, який їде своїм маршрутом, нічого не порушує.","Маршрутка їде за своїм маршрутом, а не за синіми стрілками."],
"z75":["Знак «Рух прямо або ліворуч» діє лише на тому перехресті, перед яким його поставили.","Синя стрілка — правило на одне перехрестя."],
"z76":["На знаку стрілки праворуч і ліворуч, тож на перехресті можна повернути в один із боків або розвернутися, а прямо їхати не можна.","Розвилка зі стрілок: праворуч чи ліворуч, а прямо — глухий кут."],
"z77":["Цей знак велить об’їжджати перешкоду тільки з правого боку — туди, куди показує стрілка.","Стрілка — твій маршрут: куди показує, з того боку й об’їжджаєш."],
"z78":["Знак на острівці зі стрілкою ліворуч велить об’їхати острівець тільки зліва, як показує стрілка.","Стрілка вліво — і об’їзд вліво, без варіантів."],
"z79":["На перехресті з круговим рухом об’їжджай центральний острівець (клумбу) в той бік, куди показують стрілки на знаку.","Коло — як карусель: крутишся лише в бік стрілок."],
"z80":["Дорогою зі знаком «Рух легкових автомобілів» можуть їхати не лише легковики, а й автобуси, мотоцикли, маршрутний транспорт і вантажівки до 3,5 т.","«Легкова» дорога — не лише для легковиків: пускають ще автобуси, мото й вантажівки до 3,5 т."],
"z81":["Знак мінімальної швидкості каже: не повільніше 50 км/год. Але й більше, ніж дозволяють правила, їхати не можна.","Синій знак з числом — нижня планка, а не стеля."],
"z82":["Пішохід може йти велодоріжкою лише тоді, коли немає тротуару чи пішохідної доріжки.","Велодоріжка — для велосипедів; пішки нею — лише коли тротуару немає."],
"z83":["Під цим знаком їхати можна лише з ланцюгами проти ковзання, і поставити їх треба щонайменше на два ведучі колеса.","Ланцюги — на ведучі колеса, бо саме вони тягнуть авто."],
"z84":["Знак «Дорога з одностороннім рухом» означає, що по всій ширині дороги всі їдуть в один бік. Не плутай його з круглим знаком «Рух прямо».","Квадратний знак зі стрілкою — вся дорога в один бік; кругла стрілка — наказ на перехресті."],
"z85":["Цей знак означає, що дорога з одностороннім рухом закінчилася і далі може бути зустрічний рух.","Перекреслена стрілка — односторонній рух скінчився, чекай зустрічних."],
"z86":["Знак попереджає: дорога, на яку виїжджаєш, одностороння, і рухатися нею можна лише в бік стрілки.","Стрілка на знаку — куди можна їхати поперечною дорогою."],
"z87":["Смугою для маршрутного транспорту, якщо вона йде в той самий бік, що й потік, можуть їхати також мопеди, мотоцикли без бокового причепа і велосипедисти.","Двоколісним на смузі маршруток дорога відкрита."],
"z88":["Якщо смугу для маршруток відділено переривчастою лінією, перед поворотом праворуч можна заїхати на неї і повернути вже з неї.","Переривчаста лінія — двері відчинені: заїжджай на смугу, щоб повернути праворуч."],
"z89":["На дорозі з реверсивним рухом напрямок руху на одній чи кількох смугах може змінюватися на протилежний.","Реверсивна смуга — як двері, що відчиняються в обидва боки: напрямок може змінитися."],
"z90":["Якщо знак «Напрямки руху по смугах» дозволяє з крайньої лівої смуги поворот ліворуч, звідти можна і розвернутися.","Ліва стрілка на смузі — і поворот, і розворот."],
"z91":["Така стрілка означає: щоб повернути ліворуч чи розвернутися, спершу виїжджаєш за перехрестя праворуч і об’їжджаєш клумбу.","Стрілка-петля: щоб опинитися ліворуч, спершу праворуч і навколо клумби."],
"z92":["Смуга для аварійної зупинки — порятунок, коли відмовили гальма: туди з’їжджають, щоб зупинитися. Це не місце для стоянки.","Гальма відмовили — рятуйся на аварійній смузі, а не паркуйся там."],
"z93":["Місце для розвороту призначене лише для розвороту. Повертати там ліворуч не можна.","Місце для розвороту — тільки для розвороту, як і каже назва."],
"z94":["Рекомендована швидкість — це порада, і діє вона лише до найближчого перехрестя.","Порада про швидкість живе до першого перехрестя."],
"z95":["Навіть без знака «Житлова зона» у дворах діють ті самі правила, що й у житловій зоні.","Двір — житлова зона за замовчуванням, знак не потрібен."],
"z96":["Діагональний перехід буває лише на перехрестях зі світлофором, який не переводять у режим миготливого жовтого.","Навскоси — тільки під повним контролем світлофора."],
"z97":["Табличка означає, що на цій стоянці авто можна залишати лише з вимкненим двигуном.","Стоїш тут — двигун відпочиває."],
"z98":["Тут можуть стати лише авто з розпізнавальним знаком «Водій, який перевозить дітей віком до трьох років». Саме дитяче крісло в салоні права не дає.","Місце — за знаком на авто, а не за кріслом у салоні."],
"z99":["Це місце для вантажівок, фургонів тощо: вони можуть стати тут лише на час, поки їх розвантажують чи завантажують.","Тут стоять, поки вантажать, — і ні хвилиною довше."],
"z100":["Знак 5.51 лише повідомляє назву населеного пункту: правила руху для населених пунктів на цій дорозі після нього не діють.","5.51 — це лише назва на табличці: «міські» правила не вмикаються."],
"z101":["Знак «Початок забудови населеного пункту» ставлять там, де біля дороги починаються будинки. Він обмежує швидкість до 50 км/год.","Почалися будинки — швидкість 50."],
"z102":["Червона табличка «Закрито» на знаку перед перевалом означає, що їхати через перевал не можна. Зелена «Відкрито» — можна.","Червоне «Закрито» — як червоний світлофор для перевалу."],
"z103":["Зелений фон покажчика поза населеним пунктом означає, що його встановлено на автомагістралі. На інших дорогах фон синій.","Зелений — автомагістраль, синій — інші дороги, білий — місто."],
"z104":["Літера «М» у номері дороги означає, що це міжнародна дорога.","М — Міжнародна, Н — Національна, Р — Регіональна."],
"z105":["Після постійної зміни схеми руху знак «Зміна схеми руху» тримають щонайменше три місяці, щоб водії встигли звикнути.","Нова схема — три місяці на звикання."],
"z106":["Знак «Тунель» ставлять на початку довгого тунелю — завдовжки 1000 м і більше.","Тунель зі знаком — кілометр і більше."],
"z107":["Цей знак означає, що на дорозі є окрема, відділена розміткою смуга, якою велосипедисти їдуть назустріч загальному потоку.","Зустрічна велосмуга — велосипедист їде тобі назустріч, але своєю смугою."],
"z108":["Блакитний символ на знаку АЗС означає, що там є газ. Чорний — бензин і дизель, зелений — зарядка для електромобілів.","Газ — як блакитне полум’я конфорки."],
"z109":["Табличка із силуетом вантажівки поширює дію знака на вантажівки, зокрема з причепом, з дозволеною максимальною масою понад 3,5 т.","Силует вантажівки — це про «важких»: понад 3,5 т."],
"z110":["Табличка «Обмеження по температурі» означає, що заборона діє лише в спеку — коли повітря тепліше за 28 °С.","Спека понад 28 °С — асфальт м’якне, важким тут не місце."],
"m1":["Суцільну лінію перетинати не можна. Авто, що їде 60 км/год, не підпадає під виняток для тихохідних, тож обганяти його через суцільну заборонено.","Суцільна — паркан, а не пунктир: через неї не обганяють."],
"m2":["Коли суцільна й переривчаста йдуть поруч, перетинати можна з боку переривчастої. З боку суцільної — лише щоб повернутися після обгону чи об’їзду.","Дивись на лінію зі свого боку: переривчаста — можна, суцільна — лише повернутися."],
"m3":["Подвійна суцільна відділяє зустрічні потоки на широких дорогах — з чотирма й більше смугами або на ділянках 2 + 1. Перетинати її не можна.","Дві суцільні — подвійний паркан: перелізти не можна."],
"m4":["Стоп-лінія показує, де зупинитися, коли світлофор чи регулювальник забороняє рух або стоїть знак «STOP». Зупиняйся перед нею, не заїжджаючи на неї.","Стоп-лінія — поріг: колеса до неї, а не на ній."],
"m5":["Коли розмітка і тимчасовий знак кажуть різне, слухайся знака — його ставлять, наприклад, на час ремонту, і він має перевагу.","Тимчасове б’є постійне: знак на стійці важливіший за фарбу на асфальті."],
"m6":["Переривчасту лінію можна перетинати з будь-якого боку, якщо маневр безпечний.","Пунктир — двері, відчинені з обох боків."],
"m7":["Жовта суцільна лінія біля краю дороги чи на бордюрі означає, що з цього боку не можна навіть зупинитися.","Суцільна жовта біля бордюру — суцільна заборона: навіть на хвилину не стаєш."],
"m8":["Ця жовта лінія біля краю дороги чи на бордюрі забороняє стоянку з того боку, де її нанесено. Ненадовго зупинитися можна.","Жовтий пунктир — «не паркуйся», жовта суцільна — «не зупиняйся»."],
"m9":["Основна розмітка біла, а тимчасова — жовта, щоб одразу було видно різницю.","Жовтий — колір тимчасового, як жилет дорожника."],
"m10":["Синя лінія вздовж дороги позначає місця для паркування з умовами: за гроші, на обмежений час або лише для певних людей.","Синя лінія — паркування з умовою: заплати, вклади в час або май на це право."],
"m11":["Переривчаста лінія 1.7 вздовж дороги позначає майданчик, де паркуватися можна безкоштовно. Паркування з оплатою чи обмеженням часу позначає синя лінія.","Біла — безкоштовно, синя — з умовами."],
"m12":["Червоно-біла «зебра» виділяє особливо небезпечний перехід, де ДТП трапляються частіше. Тут пильнуй подвійно.","Червоне в «зебрі» — як червоний прапорець: тут небезпечніше."],
"m13":["Жовта «сітка» на перехресті означає: якщо за ним затор, не заїжджай — застрягнеш на розмітці й заблокуєш рух.","Жовта «вафля» — не для стояння: затор попереду — чекай перед перехрестям."],
"m14":["Розмітка 1.10.2 на паркуванні позначає резервне місце для швидкої, поліції та інших екстрених служб. Іншим авто там ставати не можна.","Резерв для рятувальників: місце має бути вільним, раптом вони поспішають."],
"m15":["Якщо машини попереду стоять, не заїжджай на розмітку 1.10.2 навпроти виїзду з двору — зупинись перед нею, щоб інші могли виїхати.","Виїзд із двору — як двері: у заторі не ставай перед ними."],
"m16":["Жовта розмітка 1.17.1 показує місце зупинки автобусів, тролейбусів та іншого маршрутного транспорту. Для стоянки таксі є інша — 1.17.3.","Жовта 1.17.1 = зупинка автобуса. Таксі — це вже 1.17.3."],
"m17":["Коли рейки йдуть посередині дороги, ділянку проїзної частини на зупинці трамвая позначають розміткою 1.17.2.","Рейки посередині дороги — зупинку трамвая на дорозі позначає 1.17.2."],
"m18":["Лінію 1.1 зазвичай не перетинають, але якщо на смузі стоїть перешкода і безпечно об'їхати її інакше не вийде, перетнути можна.","Нерухома перешкода сильніша за фарбу: об'їжджай навіть через 1.1, якщо безпечно."],
"m19":["Через суцільну 1.1 можна обігнати лише один транспорт, що їде повільніше 30 км/год, і тільки коли це безпечно.","Сам-один і повільніше 30 — тільки такого можна обігнати через 1.1."],
"m20":["Виняток для лінії 1.1 діє лише для одного повільного авто. Групу з трьох вантажівок через суцільну не обганяють, навіть якщо вони їдуть 20 км/год.","Одинака — можна, колону — ні: виняток 1.1 лише для поодиноких."],
"m21":["Широка суцільна 1.2 лише показує край дороги. Її можна перетнути, наприклад щоб з'їхати на узбіччя, якщо знаки цього не забороняють.","1.2 — край дороги, а не стіна: на узбіччя можна, якщо знаки не проти."],
"m22":["Там, де лінія 1.2 біля смуги для автобусів стає переривчастою, на цю смугу можна заїжджати й іншим машинам.","Перерви в лінії — як відчинені двері: тут на смугу для автобусів можна заїхати."],
"m23":["Лінія наближення 1.6 попереджає: скоро буде 1.1, 1.11 або 1.24, де маневрувати вже не можна. Тож маневр плануй заздалегідь.","Довгі штрихи — попередження: незабаром суцільна, маневр завершуй зараз."],
"m24":["Переривчаста 1.7 на перехресті — підказка, якою траєкторією вести свою смугу через перехрестя, щоб не опинитися на чужій.","1.7 — пунктир-навігатор: веде твою смугу через перехрестя."],
"m25":["Широку переривчасту 1.8 між основною смугою і смугою повороту можна перетинати з будь-якого боку, бо вона переривчаста.","Переривчаста — значить прохідна: 1.8 перетинай з обох боків."],
"m26":["Якщо реверсивні світлофори згасли, на цій смузі вже не зрозуміло, хто має право їхати. Тому одразу перестроюйся праворуч за лінію 1.9.","Реверсивний світлофор згас — негайно праворуч за 1.9."],
"m27":["Коли реверсивні світлофори вимкнені, лінія 1.9 розділяє зустрічні потоки. Тому перетинати її, якщо вона ліворуч від тебе, не можна.","Світлофори вимкнені — 1.9 ліворуч стає межею із зустрічкою: не перетинай."],
"m28":["Якщо реверсивні світлофори зелені і обидві смуги біля 1.9 ведуть у твій бік, зустрічних там немає — лінію можна перетинати з будь-якого боку.","Обидві смуги в один бік — 1.9 перетинай вільно, з будь-якого боку."],
"m29":["З боку суцільної 1.11 перетинати зазвичай не можна, але завершити обгін чи об'їзд перешкоди і повернутися у свою смугу — дозволено.","Обгін треба довести до кінця: повернутися через суцільну 1.11 можна."],
"m30":["Розмітка 1.13 показує, де зупинитися, якщо треба пропустити машини на дорозі, яку перетинаєш. Якщо нікого немає, зупинятися не обов'язково.","1.13 — «пропусти, якщо є кого». Обов'язковий стоп — це вже стоп-лінія 1.12."],
"m31":["Напис «STOP» на дорозі попереджає: попереду стоп-лінія 1.12, біля якої може знадобитися зупинитися.","Написано STOP — чекай стоп-лінію."],
"m32":["Червоно-біла розмітка 1.15 позначає місце, де велодоріжка перетинає дорогу. Тут стеж за велосипедистами.","Червоно-біле поперек дороги — тут дорогу перетинають велосипедисти."],
"m33":["Острівець, обведений суцільною 1.1, — не місце для руху. Заїжджати на нього не можна ні щоб об'їхати затор, ні щоб зупинитися.","Острівець за суцільною — острів, до якого авто не допливають."],
"m34":["Стрілка із зображенням тупика означає, що на найближчу дорогу в цей бік повертати не можна.","Стрілка впирається в тупик — найближчий поворот закритий."],
"m35":["Якщо стрілка на крайній лівій смузі дозволяє повернути ліворуч, з цієї смуги можна й розвернутися.","Ліворуч можна — значить і розворот можна: це «ліворуч до кінця»."],
"m36":["Розмітка 1.19 попереджає: смуг у твоєму напрямку стає менше або закінчується смуга розгону, тож перестроюйся заздалегідь.","1.19 — «смуга скоро зникне»: час перестроїтися."],
"m37":["Якщо під час обгону поза містом бачиш 1.19 разом із лінією 1.6, це сигнал: завершуй обгін і повертайся у свою смугу.","1.19 плюс 1.6 — обгону кінець, повертайся у свою смугу."],
"m38":["Жовта розмітка 1.23 позначає «лежачого поліцейського» — пагорб на дорозі, який змушує знизити швидкість.","Жовте на горбі — горб на дорозі: скидай швидкість."],
"m39":["Ламані лінії 1.24 попереджають про небезпечний перехід чи велопереїзд: там погано видно, часто стаються ДТП або поруч навчальний заклад.","Лінія «нервує» зигзагом — попереду небезпечний перехід, будь напоготові."],
"m40":["Широкі жовті поперечні смуги 1.25 попереджають про кільцеву розв'язку попереду: заздалегідь знижуй швидкість.","Жовті смуги — як кола на воді: попереду кільце, пригальмуй."],
"m41":["Похилі смуги 2.3 на щиті підказують, як об'їжджати перешкоду: бік, куди дивиться їхній нижній край, — твій бік об'їзду.","Куди дивиться нижній край смуг — туди й об'їжджай."],
"m42":["Якщо від низу мосту чи тунелю до дороги 5 метрів або менше, на край наносять розмітку 2.2 — так попереджають про обмежену висоту.","Міст нижчий за 5 м — малюють 2.2: пильнуй висоту."],
"m43":["Звичайні опори й перешкоди фарбують чорно-білим, а жовто-червоним — на аварійно небезпечних ділянках, де часто стаються ДТП.","Червоне — колір тривоги: жовто-червона розмітка = тут часто аварії."],
"m44":["Світлоповертачі на стовпчиках праворуч від тебе червоні, а ліворуч — білі. Так у темряві видно, де який край дороги.","Ліворуч — біЛі (обидва слова з «л»), тож праворуч — червоні."],
"m45":["Чорно-білі смуги 2.6 на бордюрах позначають небезпечні місця: острівці, зупинки, початок розділювальної смуги, кільце, круті спуски.","Зебра на бордюрі каже: «обережно, тут небезпечне місце»."],
"m46":["Розмітка 1.28.1 позначає смугу, якою разом їдуть маршрутний транспорт і велосипедисти. Смугу лише для автобусів позначає 1.27.","1.28.1 — смуга на двох: автобус і велосипед."],
"m47":["Розмітка 1.40 — паркомісця для водіїв, які везуть дітей до 3 років і мають на авто відповідний розпізнавальний знак.","Малюк до трьох років плюс знак на авто — місце 1.40 твоє."],
"m48":["Розмітка 1.38 позначає місця, де заряджають електромобілі. Місця для людей з інвалідністю — це 1.35, межі паркомісць — 1.34.","1.38 — «розетка» на асфальті: тут заряджають електромобілі."],
"m49":["Розмітка 1.39 попереджає, що попереду ділянка, куди просто з території школи виходять на дорогу діти. Стеж за ними особливо уважно.","1.39 — шкільний дзвоник на асфальті: поруч вихід зі школи."],
"m50":["Розмітка 1.31 — це знак обмеження максимальної швидкості, намальований прямо на дорозі, щоб його було важче пропустити.","Цифра на асфальті — та сама «стеля» швидкості, що й на знаку."],
"v1":["Покажчик повороту лише повідомляє іншим про твій намір. Переваги він не дає, тож перед маневром однаково переконайся, що це безпечно.","Поворотник — це прохання, а не наказ: блимає, але дорогу не відкриває."],
"v2":["Якщо ви з сусідом одночасно перестроюєтеся в одну смугу, поступається той, у кого інше авто справа. Перевага в того, хто праворуч.","Хто справа — той і правий: його пропускаєш."],
"v3":["Задом не можна їхати там, де це особливо небезпечно: на перехрестях, переходах, мостах, у тунелях і на переїздах, а також де погано видно.","Де тісно й людно — перехрестя, перехід, міст, тунель, переїзд — задній хід вимкнено."],
"v4":["Розворот заборонено, якщо хоча б в один бік дорогу видно менше ніж на 100 метрів: можна не помітити авто, що наближається.","Видно менше сотні метрів — розворот відкладається."],
"v5":["Перед поворотом праворуч заздалегідь займи крайнє праве положення на дорозі, щоб нікому не перерізати шлях.","Праворуч повертаєш — праворуч і тримайся."],
"v6":["Виїжджаючи з двору на дорогу, ти завжди поступаєшся: і пішоходам, і всім машинам, що їдуть дорогою.","Двір — найдругорядніший: виїжджаючи, пропускай усіх."],
"v7":["Якщо права смуга вільна, а ти нікого не обганяєш і не готуєшся повертати ліворуч, їдь правою. Ліва — для випередження, об'їзду, лівих поворотів і розворотів.","Ліва смуга — для справ, права — для звичайної їзди."],
"v8":["Перед будь-яким маневром — рушаєш, перестроюєшся чи змінюєш напрямок — спершу переконайся, що це безпечно і нікому не заважає.","Будь-який рух кермом починається з погляду навколо."],
"v9":["Рушаючи від узбіччя, ти не маєш нікому заважати. Пропусти авто, що їде ззаду, — покажчик повороту переваги не дає.","Хто вже в русі — той перший; від узбіччя рушають після нього."],
"v10":["З'їжджаючи з дороги у двір, пропусти всіх, чий шлях перетинаєш: і пішохода, і велосипедиста.","З дороги у двір — пропусти і тих, хто йде, і тих, хто крутить педалі."],
"v11":["Виїжджаючи з АЗС, зупинись ще до тротуару і пропусти людей. Заїжджати на тротуар, поки там ідуть, не можна.","Тротуар — територія пішоходів: чекай перед ним, а не на ньому."],
"v12":["Перестроюючись, ти поступаєшся машинам, які вже їдуть у тій смузі, куди хочеш потрапити.","У чужій смузі ти гість: господарі смуги їдуть першими."],
"v13":["Перед розворотом заздалегідь займи крайнє ліве положення на своїй половині дороги, як перед поворотом ліворуч, якщо знаки чи розмітка не кажуть інакше.","Розворот — це «ліворуч до кінця», тож готуйся як до лівого: крайнє ліве."],
"v14":["Навіть коли їдеш головною, яка повертає ліворуч, ти фактично повертаєш ліворуч. Тож заздалегідь займи крайнє ліве положення.","Дорога повертає ліворуч — і ти повертаєш ліворуч: крайнє ліве."],
"v15":["Заздалегідь займати крайнє положення не обов'язково, коли в'їжджаєш на кільце. Для повороту ліворуч за головною чи розвороту це правило діє.","Кільце — виняток із правила крайнього положення."],
"v16":["Якщо розмітка дозволяє повертати ліворуч з двох смуг, з другої зліва теж можна. Коли смуги розписані розміткою, просто їдь за нею.","Стрілка на смузі важливіша за «крайнє положення»: їдь, куди вона вказує."],
"v17":["Розвертаючись поза перехрестям з крайнього лівого положення, ти перетинаєш шлях зустрічним машинам, тому пропускаєш їх.","Розворот перетинає зустрічку — тож зустрічні їдуть першими."],
"v18":["Якщо повертаєш ліворуч не з крайньої лівої позиції, поруч можуть їхати попутні авто. Тому пропускаєш і зустрічних, і попутних.","Не з краю — пропускаєш усіх: і тих, хто назустріч, і тих, хто поруч."],
"v19":["Якщо авто попереду розвертається, а ти повертаєш ліворуч, спершу пропусти його.","Розворот попереду — твій лівий поворот почекає."],
"v20":["Повертаючи ліворуч поза перехрестям через колії посередині дороги, пропусти трамвай, навіть попутний, що наближається ззаду.","Рейки посередині — трамвай головний: спершу він, потім твій поворот."],
"v21":["Повертаючи ліворуч, виїжджай з перехрестя одразу на свою половину дороги, а не на зустрічну смугу, навіть ненадовго.","Не «зрізай кут»: після лівого повороту ти одразу на своїй половині."],
"v22":["Повертаючи праворуч, тримайся ближче до правого краю дороги, щоб не виїхати на сусідні смуги.","Праворуч — коротко і впритул до правого краю."],
"v23":["З кільця можна з'їхати з будь-якої смуги, якщо знаки чи розмітка не кажуть інакше і ти не заважаєш попутним машинам справа.","З кола — з будь-якої смуги, але сусіда справа не підрізай."],
"v24":["Довгому автобусу можна повертати не з крайнього положення, якщо інакше він не впишеться. Але знаки й розмітка діють, і небезпеки бути не повинно.","Довгому — ширша дуга, але без порушень знаків і без ризику."],
"v25":["Розвертатися не можна ні на мостах, шляхопроводах і естакадах, ні під ними.","Міст над головою чи під колесами — розвороту немає."],
"v26":["Розвертатися на залізничному переїзді заборонено, так само як на мостах, у тунелях і на пішохідних переходах.","Переїзд — не місце для розворотів: через рейки тільки прямо."],
"v27":["Розвертатися не можна на самому пішохідному переході і ближче ніж за 10 метрів до нього — і перед ним, і за ним.","По 10 метрів з кожного боку переходу — зона без розворотів."],
"v28":["Заборона розвертатися ближче 10 метрів від переходу не стосується перехресть. Якщо на перехресті розворот дозволено, розвертатися можна.","Перехрестя має свої правила: дозволений там розворот перехід поруч не скасовує."],
"v29":["На дорозі для автомобілів розвертатися можна лише на перехрестях або там, де стоїть знак місця (5.29) чи зони (5.30) для розвороту. Розриви в розділювальній смузі — не для цього.","Розвертайся лише там, де це прямо дозволили: перехрестя або знак розвороту."],
"v30":["Смуга гальмування потрібна, щоб не гальмувати в загальному потоці. Перестроюйся на неї вчасно і тільки там скидай швидкість.","Гальмуєш на смузі гальмування — назва все підказує."],
"v31":["Смугою розгону набирай швидкість і вливайся в потік, пропускаючи тих, хто вже їде дорогою.","Смуга розгону — щоб розганятися, а не стояти; на дорозі пропускай тих, хто вже там."],
"v32":["Якщо назад погано видно, попроси когось підказувати. Їхати навмання, навіть з аварійкою чи звуковим сигналом, не можна.","Не бачиш, що ззаду, — візьми «очі напрокат»: попроси когось підказати."],
"v33":["Здавати назад заборонено і в тунелі, і на в'їзді чи виїзді з нього. Доведеться їхати далі і шукати інший шлях.","Біля тунелю і в ньому задній хід вимкнено."],
"v34":["Коли видимість недостатня, як у густому тумані, їхати заднім ходом не можна — краще знайти інший шлях до потрібного місця.","Туман — заднього ходу немає: назад наосліп не їдуть."],
"v35":["На односторонній дорозі задом можна їхати, лише якщо інакше до потрібного місця не під'їхати і ти нікому не створюєш небезпеки.","Одностороння — задній хід лише як останній вихід, і тільки безпечно."],
"v36":["На парковці, де черговість не визначена правилами, поступається той, до кого інше авто наближається справа. Тож пропускаєш машину справа.","Не знаєш, хто головний, — глянь праворуч: машина справа їде першою."],
"v37":["Якщо смуги не позначені, водії самі вирішують, скільки їх уміщується, зважаючи на ширину дороги, розміри машин і безпечні проміжки між ними.","Немає розмітки — кількість смуг визначаєш на око, але із запасом місця між машинами."],
"v38":["На дорозі з двома смугами в один бік тримайся правого краю. Ліворуч виїжджають лише для випередження, об'їзду чи підготовки до лівого повороту або розвороту.","Права — твій дім, ліва — лише для справ: випередити, об'їхати, повернути."],
"v39":["На вузькій дорозі без суцільної на зустрічну виїжджають лише для обгону, об'їзду перешкоди або дозволеної зупинки біля лівого краю в населеному пункті.","Зустрічка — лише в трьох випадках: обігнати, об'їхати, зупинитися зліва в населеному пункті."],
"v40":["Виїхавши на зустрічну смугу, щоб щось об'їхати, ти там гість. Перевага в того, хто їде назустріч своєю смугою.","На чужій смузі господар — зустрічний."],
"v41":["Якщо в кожен бік по дві смуги чи більше, виїжджати на зустрічну половину дороги заборонено — навіть щоб об'їхати затор.","Дві смуги в твій бік — зустрічна половина зачинена."],
"v42":["На дорозі з трьома смугами крайня ліва — не для звичайної їзди. Займай її, коли праві зайняті, або щоб повернути ліворуч чи розвернутися.","Ліва смуга — запасна: коли праві повні або коли тобі ліворуч."],
"v43":["У населеному пункті на односторонній дорозі ліву смугу можна займати й для зупинки біля лівого краю, якщо зупинятися там не заборонено.","Рух в один бік — обидва краї для зупинки, якщо її там не заборонено."],
"v44":["Важка вантажівка поза населеним пунктом на дорозі з трьома смугами може виїхати на крайню ліву лише щоб повернути ліворуч або розвернутися.","Важкий вантаж — ліворуч лише по ділу: поворот або розворот."],
"v45":["У місті на односторонній дорозі вантажівка понад 3,5 т може зайняти ліву смугу ще й щоб зупинитися зліва для завантаження чи розвантаження, де це дозволено.","Вантажівці ліва смуга — лише щоб повернути, розвернутися або розвантажитися."],
"v46":["Якщо машина не може їхати швидше 40 км/год, вона тримається якнайближче до правого краю, щоб не заважати іншим.","Не тягнеш 40 — тримайся правого краю."],
"v47":["Їхати попутною колією на рівні з дорогою можна, якщо знаки чи розмітка не забороняють і ти не заважаєш трамваю.","На колії ти в гостях у трамвая: їхати можна, заважати — ні."],
"v48":["Якщо посередині дороги попутна колія на одному рівні з нею, ліворуч повертаєш саме з колії, якщо знаки 5.16, 5.18 чи розмітка 1.18 не кажуть інакше.","Колія посередині — це і є твоє «крайнє ліве» для повороту."],
"v49":["Знаки 5.16–5.19.3 перед перехрестям показують, як їхати по смугах. Якщо вони є, на попутну колію на перехресті виїжджати не можна.","Є знаки смуг перед перехрестям — колію залиш трамваю."],
"v50":["На трамвайну колію зустрічного напрямку виїжджати не можна взагалі — навіть щоб об'їхати перешкоду.","Зустрічна колія — дорога трамвая, що їде назустріч: туди ні колесом."],
"v51":["Якщо колії відокремлені від дороги бордюром, виїжджати на них не можна, навіть коли вони попутні і стоїть затор.","Бордюр — це паркан: за ним трамвайна територія, не твоя."],
"v52":["Розділювальна смуга не призначена ні для руху, ні для стоянки. Об'їжджати нею затор заборонено.","Розділювальна — щоб розділяти, а не щоб їздити."],
"v53":["Якщо смуги розмічені, їдь чітко в одній із них. Їхати посередині, займаючи дві смуги одразу, заборонено.","Одна машина — одна смуга."],
"v54":["На переривчасту лінію можна наїжджати лише тоді, коли перестроюєшся. Їхати по ній, ніби по рейці, не можна.","Переривчасту переїжджають, а не їздять по ній."],
"v55":["У щільному потоці смугу міняють лише по ділу: щоб об'їхати перешкоду, повернути, розвернутися чи зупинитися. Шукати «швидшу» смугу не можна.","Щільний потік — без «шашок»: смугу міняєш лише по ділу."],
"v56":["Повернувши на дорогу з реверсивною смугою, перестроюйся на неї лише після реверсивного світлофора, який дозволяє рух.","Спершу дозвіл від реверсивного світлофора — потім реверсивна смуга."],
"v57":["Тротуар — для пішоходів. Їхати ним, щоб об'їхати затор, заборонено, навіть якщо людей там немає.","Тротуар — не об'їзна дорога."],
"v58":["До крамниці можна під'їхати тротуаром, якщо іншого під'їзду немає. Але пішоходи там головні — їх треба пропускати.","На тротуарі ти гість: пішохід завжди перший."],
"v59":["Мопеди їдуть дорогою лише в один ряд, якомога правіше, у правій смузі. Їхати поруч по двоє не можна.","Мопеди — як намистинки на нитці вздовж правого краю: один за одним."],
"v60":["На мопеді повертати ліворуч чи розвертатися можна лише на дорозі з однією смугою в кожен бік і без трамвайної колії посередині.","Мопеду ліворуч — лише на простій дорозі: по смузі в кожен бік і без рейок посередині."],
"v61":["Гужовий віз може їхати узбіччям, якщо при цьому не заважає пішоходам.","Узбіччя можна ділити з пішоходами, але вони там важливіші."],
"p1":["У населеному пункті, якщо знаки не кажуть інакше, їдь не швидше 50 км/год.","Населений пункт — пів сотні: 50 км/год."],
"p2":["У житловій зоні, де поруч гуляють діти й ходять люди, не можна їхати швидше 20 км/год.","Житлова зона — 20: тут люди вдома, а не на трасі."],
"p3":["Поза населеним пунктом на звичайній дорозі без розділювальної смуги легковик зі стажем водія понад 2 роки може їхати до 90 км/год.","Звичайна траса — 90, з розділювальною — 110, автомагістраль — 130."],
"p4":["На автомагістралі легковик без причепа, якщо водій має понад 2 роки стажу, може їхати до 130 км/год.","Автомагістраль — найшвидша дорога: 130 км/год."],
"p5":["Поки стаж менше 2 років, поза населеним пунктом їдь не швидше 70 км/год, навіть там, де іншим можна швидше.","Новачок за містом — 70, поки досвіду менше 2 років."],
"p6":["Обганяти заборонено на самому переїзді і ближче ніж за 100 метрів до нього.","Сотня метрів до рейок — зона без обгонів."],
"p7":["Коли тебе обганяють, не заважай: не прискорюйся і не роби нічого, що ускладнить обгін.","Тебе обганяють — не змагайся: дай завершити."],
"p8":["Тримай таку дистанцію, щоб устигнути зупинитися, якщо машина попереду різко загальмує. Точного числа немає, орієнтир — щонайменше 2 секунди.","Авто попереду минуло стовп — ти доїжджаєш до нього не раніше ніж за 2 секунди."],
"p9":["Навіть у межах дозволеного обирай швидкість з огляду на ситуацію на дорозі, вантаж і стан свого авто, щоб завжди контролювати машину.","Знак каже «не більше», а дорога, вантаж і авто підказують, скільки саме."],
"p10":["Уночі на темній дорозі їдь так, щоб устигнути зупинитися в межах того, що бачиш у світлі фар.","Не їдь швидше, ніж бачать твої очі."],
"p11":["У тумані 90 км/год — лише верхня межа. Їхати треба так, щоб устигнути зупинитися в межах того, що бачиш.","Ліміт — це стеля, а в тумані стелю опускає видимість."],
"p12":["Якщо на смузі попереду перешкода, одразу скидай швидкість аж до зупинки або об'їдь її, якщо це безпечно для інших.","Перешкода — спершу гальмо; об'їзд — лише якщо безпечно."],
"p13":["Авто, що мчить назустріч твоєю смугою, — пряма небезпека. Одразу гальмуй, за потреби до повної зупинки, а не з'ясовуй, хто правий.","Хтось їде на тебе — не доводь свою правоту, гальмуй."],
"p14":["Швидше 50 км/год у населеному пункті можна лише там, де знаки дозволяють більшу швидкість.","50 — правило за замовчуванням; більше — лише коли це дозволяє знак."],
"p15":["Обмеження 70 км/год для новачків діє за містом. У населеному пункті всі — і новачки, і досвідчені — їдуть не швидше 50 км/год.","У місті всі рівні — 50; різниця для новачків лише за містом."],
"p16":["У пішохідній зоні, навіть біля власного дому, їдь не швидше 20 км/год.","Пішохідна чи житлова зона — та сама двадцятка."],
"p17":["Знак 5.51 означає, що на цій дорозі правила населеного пункту не діють. Тож ліміт як за містом: на дорозі без розділювальної смуги — 90 км/год.","Знак 5.51 — село «не рахується»: їдь як за містом."],
"p18":["Автобус чи мікроавтобус з організованою групою дітей за містом їде не швидше 80 км/год на будь-якій дорозі, навіть на автомагістралі.","Діти на борту — максимум 80, навіть на автомагістралі."],
"p19":["З причепом легковик за містом їде не швидше 80 км/год, хоч би яким був стаж і навіть на автомагістралі.","Причіп — гиря на швидкості: більше 80 не можна."],
"p20":["Мотоцикл поза населеним пунктом — до 80 км/год на будь-якій дорозі, навіть з розділювальною смугою.","Мотоцикл за містом — 80 на будь-якій трасі."],
"p21":["Тут діють два обмеження: 80 км/год для причепа і 70 км/год для новачка. Їхати треба за меншим із них — 70.","Два обмеження одночасно — їдь за меншим."],
"p22":["Якщо вантажівка везе людей у кузові, вона їде не швидше 60 км/год.","Люди в кузові — 60, не більше."],
"p23":["На мопеді поза населеним пунктом можна їхати не швидше 60 км/год.","Мопед за містом — 60, як вантажівка з людьми в кузові."],
"p24":["Великий автобус (не мікроавтобус) за містом — до 90 км/год на будь-якій дорозі, навіть на автомагістралі.","Великий автобус — 90 скрізь за містом, автомагістраль не виняток."],
"p25":["Обмеження 90 км/год стосується великих автобусів, а не мікроавтобусів. Тож мікроавтобус на автомагістралі підпадає під загальний ліміт — 130 км/год.","Мікроавтобус — не автобус: на автомагістралі йому загальні 130."],
"p26":["130 км/год можна лише на дорозі зі знаком «Автомагістраль». Якщо знака немає, а проїзні частини розділені розділювальною смугою, — до 110 км/год.","Немає знака автомагістралі — немає 130: розділювальна смуга дає 110."],
"p27":["Їхати до 130 км/год можна саме тоді, коли дорогу позначено знаком 5.1 «Автомагістраль». Кількість смуг чи відсутність сіл поруч нічого не змінюють.","130 дає знак, а не ширина дороги."],
"p28":["Якщо в кузові немає людей, вантажівка підпадає під загальний ліміт: на звичайній дорозі за містом — 90 км/год.","Без людей у кузові — звичайні 90."],
"p29":["Буксируючи авто, їдь не швидше 50 км/год, навіть якщо знак дозволяє 70.","Буксир — це завжди не більше 50, що б не писав знак."],
"p30":["Навіть якщо на дорозі дозволено більше, не можна їхати швидше, ніж передбачено технічною характеристикою твого авто.","Технічна межа авто — теж обмеження, і дорожній знак її не скасовує."],
"p31":["Число 60 на розпізнавальному знаку твого авто — твоя максимальна швидкість. Навіть де дозволено 90 км/год, тобі — не більше 60.","Що написано на твоєму авто — те й твоя межа, хоч би що казали знаки на дорозі."],
"p32":["Так, без причини повзти по вільній дорозі й збирати чергу позаду не можна — це заважає іншим.","Занадто повільно — теж порушення: не створюй затор на порожній дорозі."],
"p33":["Різко гальмувати можна лише тоді, коли інакше не уникнути аварії. «Провчити» того, хто їде впритул, так не можна.","Різке гальмо — лише для порятунку, не для помсти."],
"p34":["Обмеження швидкості не ставлять «просто так»: поруч мають бути знаки, які пояснюють, яка там небезпека чи до якого об'єкта ти наближаєшся.","Обмеження завжди з поясненням: знак швидкості плюс знак «чому»."],
"p35":["Жовтий фон у знака обмеження швидкості означає, що обмеження ввели тимчасово, а не назавжди.","Жовтий фон — обмеження тимчасове."],
"p36":["Тимчасово обмежити швидкість знаками на жовтому фоні можуть лише через дорожні роботи, масові чи спеціальні заходи або погодні явища.","Жовтий знак — три причини: ремонт, захід або негода."],
"p37":["Постійно швидкість обмежують на небезпечних ділянках, біля нерегульованих переходів, станцій патрульної поліції та дитячих закладів — шкіл, садків, таборів.","Де діти — там постійно повільніше."],
"p38":["Безпечну дистанцію й інтервал не задають числом — їх обирають, зважаючи на швидкість, ситуацію на дорозі, вантаж і стан авто.","Швидше, складніша дорога, важчий вантаж — більший запас."],
"p39":["Безпечна дистанція — це коли тобі вистачає місця просто загальмувати, не об'їжджаючи і не з'їжджаючи на узбіччя.","Безпечна дистанція — коли рятує саме гальмо, без керма."],
"p40":["Їдучи повільно за іншим тихохідним авто за містом, залиш між вами місце, куди зможе повернутися той, хто вас обганяє.","Між двома повільними — «кишеня» для того, хто обганяє."],
"p41":["Проміжок можна не залишати, якщо ти на тихохідному авто й подаєш сигнал, що збираєшся обганяти чи об'їжджати.","Подаєш сигнал, що обганяєш, — «кишеню» тримати не обов'язково."],
"p42":["Залишати місце для тих, хто обганяє, мусять повільні машини, що їдуть за містом не швидше 40 км/год.","До 40 — тихохід: лишай місце для тих, хто обганяє."],
"p43":["Об'їжджаючи велосипедиста, тримай безпечний проміжок збоку, щоб не створити для нього небезпеки.","Велосипедист — не бордюр: об'їжджай із запасом."],
"p44":["Якщо на вузькій дорозі перешкода стоїть на твоїй смузі, саме ти пропускаєш зустрічне авто.","Чия смуга з перешкодою — того й черга чекати."],
"p45":["Якщо твоя широка вантажівка заважає зустрічним на вузькій дорозі, поступаєшся саме ти.","Хто ширший і заважає — той і пропускає."],
"p46":["На крутому схилі з перешкодою поступається той, хто їде вниз, навіть якщо перешкода на твоїй смузі: рушати вгору після зупинки значно важче.","Спускаєшся — пропускаєш. Піднімаєшся — їдеш."],
"p47":["Якщо авто позаду вже пішло на обгін, не виїжджай — підріжеш його. Почекай, поки воно проїде, і лише тоді вирішуй, чи обганяти.","Перед обгоном глянь у дзеркало: там уже хтось обганяє — ти чекаєш."],
"p48":["Лівий поворотник попереду означає, що водій збирається повертати чи перестроюватися ліворуч. Почнеш обгін — можете зіткнутися, тому обганяти не можна.","Поворотник ліворуч попереду — твій обгін на паузі."],
"p49":["Перш ніж виїхати на зустрічну, переконайся, що вона вільна на всю відстань, потрібну для обгону, — щоб устигнути його завершити без ризику.","Обгін починай, лише коли бачиш вільну зустрічку до самого його кінця."],
"p50":["Обгін — це не лише виїхати, а й повернутися. Переконайся, що зможеш стати назад у свою смугу, не підрізаючи того, кого обганяєш.","Обгін без місця, щоб повернутися, — квиток в один кінець."],
"p51":["Якщо ти їдеш повільно і тебе ніяк не можуть обігнати, допоможи: тримайся якомога правіше, а коли треба — з'їдь на узбіччя й пропусти чергу.","Черга за тобою — сигнал прийняти вправо й пропустити."],
"p52":["Після першого обгону можна не повертатися у свою смугу, лише якщо це не створить небезпеки зустрічним і не завадить швидшим авто позаду.","Лишатися на зустрічці можна, лише коли нікому не заважаєш: ні тим, хто назустріч, ні тим, хто ззаду."],
"p53":["На перехресті обганяти не можна взагалі — навіть якщо ти на головній дорозі чи перехрестя має світлофор.","Перехрестя ставить хрест на обгоні."],
"p54":["У місті не можна обганяти ближче ніж за 50 метрів до пішохідного переходу: авто, яке ти обганяєш, може закривати від тебе пішохода.","Місто: 50 м до зебри — без обгону. Сусіднє авто може ховати пішохода."],
"p55":["Поза містом обгін заборонено ближче ніж за 100 метрів до переходу. До переходу 80 м — це вже зона заборони, тож обганяти не можна.","За містом швидкості вищі — і зона без обгону перед зеброю більша: 100 м."],
"p56":["На вершині підйому ти не бачиш, хто їде назустріч з-за горба, тому обганяти там заборонено.","Не бачиш, що за горбом, — не обганяй."],
"p57":["На мостах обганяти не можна, навіть якщо міст довгий і рівний, а зустрічна вільна. Це заборона через саме місце, а не через видимість.","Міст, естакада, шляхопровід — над землею без обгону."],
"p58":["На крутому повороті обганяти не можна, навіть якщо розмітка переривчаста: за поворотом не видно зустрічних.","Крутий поворот ховає зустрічних — тож обгону там немає, хоч яка розмітка."],
"p59":["У тумані видимість менше 300 м уже вважається недостатньою, а за такої видимості обганяти заборонено. 150 м — точно замало.","Туман — сліпий обгін. Не бачиш далеко — не виїжджай на зустрічку."],
"p60":["Якщо авто попереду саме обганяє, обганяти його не можна: вийде «обгін обгону», і на зустрічній стане надто тісно й небезпечно.","Того, хто обганяє, не обганяють. Один обгін за раз."],
"p61":["Тунель — одне з місць, де обгін заборонено, хоч би яким добрим там було освітлення.","Тунель — як труба: їдеш своєю смугою аж до виїзду."],
"p62":["Якщо у твоєму напрямку дві смуги чи більше, виїжджати на зустрічну для обгону заборонено. Повільніших можна оминути сусідньою смугою свого напрямку.","Дві смуги твої — зустрічні не чіпай."],
"p63":["Ти не виїжджаєш на зустрічну, а просто їдеш лівою смугою свого напрямку швидше за вантажівку. Це випередження, а не обгін, тож так можна.","Немає зустрічки — немає обгону. Своя ліва смуга — це випередження."],
"p64":["Знак обмеження 100 не дозволяє їхати швидше, ніж можна саме твоєму транспорту. Легковику з причепом — не більше 80 км/год, хоч що показує знак.","Причіп стримує апетит: з ним максимум 80, навіть під знаком 100."],
"p65":["Колону з маячком позаду обганяти не можна, якщо маячок будь-якого кольору, крім оранжевого: оранжевий переваги в русі не дає.","Оранжевий маячок — лише попередження. Будь-який інший колір — колону не обганяй."],
"p66":["Переїзди, естакади й тунелі — місця, де обганяти не можна за жодних умов. А на прямій рівній дорозі з однією смугою в кожен бік обгін можливий, якщо це безпечно.","Пряма й рівна — так. Переїзд, естакада, тунель — ні."],
"a1":["Якщо колона їде без супроводу, кожна її машина має знак «Колона» й увімкнене ближнє світло — так інші одразу бачать, що це одна група.","Колона = знак «Колона» + ближнє світло на кожній машині."],
"a2":["Без супроводу колона їде лише в один ряд, якомога ближче до правого краю дороги, щоб не заважати іншим.","Колона — як намистинки на нитці: одна за одною біля правого краю."],
"a3":["Довгу колону без супроводу ділять на групи щонайбільше по п'ять машин, а між групами лишають місце, щоб інші могли обігнати групу.","Група в колоні — як пальці на руці: не більше п'яти."],
"a4":["Якщо колона зупинилася на дорозі, аварійку вмикають усі її машини, а не лише перша й остання, — щоб кожну було добре видно.","Колона стоїть — блимають усі."],
"a5":["Вклинитися в колону й їхати разом з нею не можна, навіть якщо між машинами є місце. Ці проміжки — частина колони, а не вільна смуга.","Колона — закрита компанія: прилаштуватися до неї не можна."],
"a6":["Двір — це завжди житлова зона, навіть без знака. Знак потрібен для інших частин міста, які теж роблять житловою зоною.","Двір = житлова зона за замовчуванням. Знак не потрібен."],
"a7":["У житловій зоні пішохід може йти й посеред дороги, і перевага в нього. Але й він не повинен без причини заважати машинам.","Житлова зона: пішохід тут господар, але не хуліган."],
"a8":["Через житлову зону не можна їхати наскрізь, щоб зрізати шлях. Заїжджати туди варто, лише якщо тобі треба саме туди.","Двір — не дорога навпростець. Транзитом крізь житлову зону — ні."],
"a9":["У житловій зоні став авто лише у відведених для цього місцях і так, щоб не заважати людям та проїзду спецтранспорту.","Житлова зона: стоянка лише у відведеному місці, а не де заманеться."],
"a10":["У житловій зоні не можна стояти з увімкненим двигуном — навіть щоб прогріти авто. Там гуляють люди й діти, вихлоп їм ні до чого.","Двір — не для вихлопу: став і глуши двигун."],
"a11":["Вантажівкам у житлову зону зазвичай зась. Виняток — ті, що працюють саме там: обслуговують будинки, заклади чи людей у цій зоні.","Вантажівка у двір — тільки у справах цього двору."],
"a12":["Вчитися водити не можна в житловій зоні, а також на автомагістралях і дорогах для автомобілів.","Навчальна їзда — не там, де діти гуляють, і не там, де мчать на великих швидкостях."],
"a13":["У пішохідну зону можуть заїхати лише «свої»: машини тих, хто там живе чи працює, тих, хто обслуговує зону, а також авто зі знаком «Водій з інвалідністю».","Пішохідна зона — для своїх: мешканці, працівники, обслуга."],
"a14":["Виїжджаючи з пішохідної зони на дорогу, ти поступаєшся всім: машинам, пішоходам, велосипедистам.","Із зони виїжджаєш — усіх пропускаєш."],
"a15":["Головна ознака автомагістралі — вона ніде не перетинається з іншими дорогами чи коліями на одному рівні: усі перетини — над або під нею.","Магістраль — без перехресть: тільки над або під."],
"a16":["Виїжджаючи на автомагістраль, ти поступаєшся тим, хто вже по ній їде. Вони не мусять звільняти тобі смугу — шукай вільне місце в потоці.","Заїжджаєш на магістраль, як у річку: вливаєшся в потік, а не розштовхуєш його."],
"a17":["Важким вантажівкам понад 3,5 т на автомагістралі можна їхати тільки першою і другою смугами, а далі ліворуч — уже ні.","Важка вантажівка тримається правої частини: смуги перша й друга, не далі."],
"a18":["Просто так зупинитися на автомагістралі не можна ні на узбіччі, ні на смузі. Для цього є спеціальні місця для стоянки, позначені знаками.","Магістраль — не для «на хвилинку»: зупинка лише там, де знак місця стоянки."],
"a19":["Технологічний розрив у розділювальній смузі — не місце для розвороту. На дорогах для автомобілів і автомагістралях заїжджати туди заборонено.","Технологічний розрив — зачинені двері: в'їзд заборонено."],
"a20":["Проскочивши з'їзд, не здавай назад — на автомагістралі задній хід заборонено. Просто їдь до наступного з'їзду.","На магістралі немає «назад» — є лише «наступний з'їзд»."],
"a21":["Дорога для автомобілів має майже ті самі правила, що й автомагістраль. Різниця: лише на автомагістралі заборонено рух транспорту, який не може їхати 40 км/год.","Не тягнеш 40 — на автомагістраль зась. На дорогу для автомобілів ця заборона не поширюється."],
"a22":["Пішоходи переходять автомагістраль лише під нею або над нею — підземними чи надземними переходами. Звичайного наземного переходу там бути не може.","Через магістраль — або під, або над. По землі — ніколи."],
"a23":["Якщо авто зламалося на автомагістралі, увімкни аварійку й зроби все, щоб прибрати його праворуч, за межі дороги. Стояти на смузі там дуже небезпечно.","Авто зламалося — аварійку вмикай, вправо з дороги прибирай."],
"a24":["Особливі правила для гірських доріг діють там, де стоять знаки «Крутий підйом» і «Крутий спуск».","Гірські правила вмикають знаки крутого підйому й спуску, а не висота над морем."],
"a25":["Якщо на гірській дорозі важко роз'їхатися, поступається той, хто їде вниз, тобто ти. Тому, хто їде вгору, зупинитися й знову рушити значно важче.","Вниз їдеш — вгору пропускаєш."],
"a26":["Гірські гальма обов'язкові для важкого транспорту: вантажівок понад 3,5 т, тракторів і автобусів — якщо виробник їх установив.","Гірські гальма — для важкої трійки: вантажівка, трактор, автобус."],
"a27":["Автобусу на підйомі гірської дороги мало самого ручника — водій має підкласти противідкотні упори під колеса, щоб машина точно не покотилася.","Важка машина на схилі — упори під колеса, і вона не відкотиться."],
"a28":["На гірській дорозі не можна котитися з заглушеним двигуном і вимкненою передачею чи зчепленням — так машину значно важче втримати.","У горах «накатом» не їздять: двигун працює, передача ввімкнена."],
"a29":["Буксирувати на тросі чи іншому гнучкому зчепленні гірськими дорогами заборонено: на крутих підйомах і спусках це надто небезпечно.","Гори й трос не дружать: у горах буксирування на тросі — ні."],
"a30":["У горах в ожеледицю буксирувати заборонено взагалі — навіть на жорсткому зчепленні. Слизько, а схили круті.","Гори + лід = жодного буксирування."],
"s1":["Не зупиняйся на переході й ближче ніж за 10 метрів до нього з обох боків — машина закриє пішоходів від інших водіїв. Виняток — щоб пропустити пішоходів.","Зебра любить простір: по 10 м з кожного боку."],
"s2":["Біля зупинки автобуса без посадкового майданчика не зупиняйся ближче ніж за 30 метрів від покажчика з обох боків — це місце для маршрутного транспорту.","Зупинка автобуса — по 30 м з кожного боку для нього, не для тебе."],
"s3":["Біля перехрестя без переходу не зупиняйся ближче ніж за 10 метрів до краю дороги, яку перетинаєш, і на самому перехресті теж.","Перехрестя тримає дистанцію: 10 м від краю поперечної дороги без зупинки."],
"s4":["Ставити авто на стоянку ближче ніж за 50 метрів до залізничного переїзду не можна, а зупинятися на самому переїзді заборонено взагалі.","Потяг — велика річ, тож і відстань велика: 50 м без стоянки."],
"s5":["На мостах зупинятися не можна взагалі, як і на естакадах, шляхопроводах, під ними та в тунелях.","Міст — для проїзду, не для зупинки."],
"s6":["У місті ліворуч стати можна на дорозі з однією смугою в кожен бік без трамвая посередині й без суцільної 1.1 або на односторонній. Інакше — лише праворуч.","Ліворуч — лише там, де дорога вузька й проста або одностороння."],
"s7":["Виходячи з машини, подбай, щоб вона не покотилася сама і щоб ніхто не зміг нею скористатися: ручник, передача, замкнені двері.","Залишаєш авто — «гальмо, передача, замок»."],
"s8":["Зупинятися й ставати на стоянку треба передусім у спеціальних місцях або на узбіччі. Біля правого краю дороги — лише якщо таких місць немає чи стати там неможливо.","Спершу кишеня чи узбіччя, і лише потім — край дороги."],
"s9":["Якщо на узбіччя стати не можна і спецмісць поруч немає, зупинись біля правого краю дороги, якомога правіше, щоб не заважати іншим.","Узбіччя розмокло — тримайся правого краю. За містом ліворуч не стають."],
"s10":["Ліворуч у місті можна стати лише тоді, коли потоки не розділяє суцільна 1.1. Якщо вона є — зупиняйся тільки праворуч.","Суцільна посередині — ліва сторона під замком."],
"s11":["Біля розділювальної смуги чи бульвару зупинятися й ставати на стоянку не можна — навіть ненадовго.","Розділювальна смуга — не узбіччя: біля неї не стають."],
"s12":["Ставити машини на дорозі у два ряди заборонено — навіть якщо лишається проїзд або водій сидить за кермом.","Дорога — не склад: легковики стоять в один ряд."],
"s13":["Мотоцикли без коляски, а також велосипеди й мопеди можна ставити у два ряди — вони вузькі. Решту транспорту — лише в один ряд.","Два колеса — два ряди."],
"s14":["Ставити авто під кутом до краю дороги можна там, де воно не заважатиме проїжджати іншим машинам.","Під кутом — так, якщо кут не стирчить на шляху інших."],
"s15":["Біля тротуару на рівній ділянці під кутом ставай лише передом до тротуару — так вихлопні гази не йдуть на людей.","Носом до тротуару, вихлопом від людей."],
"s16":["На підйомі все навпаки: під кутом біля тротуару ставай лише задньою частиною до нього. На рівному — передом, на підйомі — задом.","Рівно — носом до тротуару, підйом — кормою."],
"s17":["Ця табличка означає: машину ставиш на дорозі вздовж тротуару, зовсім не заїжджаючи на нього.","Ця табличка — «рівненько вздовж бордюру, усі колеса на дорозі»."],
"s18":["Таблички зі способом стоянки біля тротуару чи на ньому діють лише для легковиків і мотоциклів, і ставати треба саме так, як намальовано.","На тротуар за табличкою — лише легковик і мотоцикл, як на картинці."],
"s19":["На схилі вздовж краю дороги поверни керовані колеса так, щоб машина не могла сама покотитися.","Схил — поверни колеса, і авто не втече."],
"s20":["На схилі можна ставити авто під кутом до краю, якщо воно нікому не заважає і точно не покотиться саме.","Схил: дві умови — не заважаєш і не котишся."],
"s21":["На трамвайній колії ліворуч зупинятися можна лише тоді, коли цього вимагають правила, — наприклад, пропускаючи зустрічних перед поворотом ліворуч. І не заважаючи трамваю.","Ліва колія — не стоянка: стоїш там лише тоді, коли правила змушують."],
"s22":["Якщо колія біля правого краю, на ній можна зупинитися, щоб висадити чи взяти пасажирів або виконати вимоги правил, — але не заважаючи трамваю.","Права колія — і для пасажирів можна. Ліва — лише за вимогою правил."],
"s23":["На залізничному переїзді зупинятися заборонено взагалі, навіть на мить, щоб висадити пасажира, — і шлагбаум тут нічого не змінює.","Переїзд — лише проїжджати. Зупинка на рейках — табу."],
"s24":["Під шляхопроводом зупинятися не можна, навіть щоб відповісти на дзвінок. Знайди для цього дозволене безпечне місце.","Міст над тобою — зупинка під забороною."],
"s25":["На Т-подібному перехресті з суцільною лінією чи розділювальною смугою навпроти бокового проїзду зупинитися можна. Це виняток із заборони стояти біля перехресть.","Т-перехрестя з суцільною: навпроти «ніжки» букви Т стати можна."],
"s26":["Біля виїзду з двору чи паркінгу не можна навіть зупинитися — заблокуєш тих, хто виїжджає. А біля переїзду й контейнерів заборонено лише стоянку.","Виїзд — святе: поруч навіть на хвилинку не стають, щоб нікого не замкнути."],
"s27":["Зупинившись, лиши іншим щонайменше 3 метри до протилежного краю дороги, щоб вони могли проїхати. 2,5 м — замало.","Правило трьох метрів: лишається менше — шукай інше місце."],
"s28":["Якщо в зупинки є посадковий майданчик, 30 метрів міряють від нього. Від знака рахують лише тоді, коли майданчика немає.","Є майданчик — міряй від нього. Немає — від знака."],
"s29":["Біля позначеного місця дорожніх робіт не зупиняйся ближче ніж за 10 метрів, якщо твоє авто заважатиме техніці, що там працює.","Техніці потрібен простір: 10 м від ремонту дороги."],
"s30":["Не зупиняйся там, де інші не зможуть тебе об'їхати чи роз'їхатися із зустрічними, — навіть щоб швидко висадити пасажира.","Якщо після твоєї зупинки ніхто не проїде — це місце не для зупинки."],
"s31":["Не можна зупинятися так, щоб твоя машина закривала іншим водіям дорожні знаки чи світлофор, — вони не побачать важливої інформації.","Твоє авто не має бути ширмою для знаків."],
"s32":["Біля виїзду з двору, АЗС чи паркінгу не зупиняйся ближче ніж за 10 метрів і в самому місці виїзду — щоб не блокувати тих, хто виїжджає.","Біля виїзду — 10 м вільних, щоб сусід міг виїхати."],
"s33":["Де не можна зупинитися, там тим паче не можна ставати на стоянку — стоянка ж довша за зупинку.","Не можна на хвилинку — не можна й надовго."],
"s34":["Ставлячи легковик на краю тротуару, лиши пішоходам щонайменше 2 метри, щоб вони спокійно пройшли.","Тротуар ділиш чесно: 2 м — пішоходам."],
"s35":["За містом не став авто на небезпечному повороті чи на горбі, якщо видно менше ніж на 100 метрів хоча б в один бік: тебе помітять надто пізно.","Поворот чи горб: видно менше 100 м — стоянки немає."],
"s36":["Не можна ставити авто так, щоб воно перекрило прохід пішоходам: вони не мусять обходити тебе дорогою.","Пішохідний шлях — не твоє паркомісце."],
"s37":["Біля сміттєвих контейнерів не став авто ближче ніж за 5 метрів, щоб сміттєвоз міг під'їхати.","Сміттєвозу треба місце: 5 м від контейнерів."],
"s38":["На газоні ставати заборонено завжди — навіть біля власного будинку і навіть коли інших вільних місць немає.","Газон — для трави, а не для коліс."],
"s39":["Поза містом у темряві не лишай авто на узбіччі чи біля краю дороги — лише на майданчику для стоянки або взагалі поза дорогою. Так само, коли погано видно.","Темно за містом — стоянка лише поза дорогою."],
"s40":["Так, це порушення. Залишаючи авто навіть на хвилину, захисти його: щоб воно не покотилося, щоб ніхто не сів і не поїхав.","Заведене авто з відчиненими дверима — запрошення для викрадача."],
"s41":["Навіть коли авто вже стоїть, не відчиняй двері, якщо можеш зачепити велосипедиста чи завадити іншим. Спершу глянь у дзеркало.","Перш ніж відчинити двері — дзеркало. Велосипедист позаду важливіший за поспіх."],
"s42":["Якщо авто заглохло на переході, спершу спробуй прибрати його звідти. Не виходить — вмикай аварійку, щоб тебе всі бачили.","Спершу прибери, не можеш — попередь аварійкою."],
"s43":["Коли зупинитися довелося через погане самопочуття, поломку, небезпечний вантаж чи перешкоду, — це вимушена зупинка: інакше просто не можна.","Вимушена — бо змусили обставини: поломка, вантаж, здоров'я, перешкода."],
"s44":["Посадка й висадка пасажирів чи розвантаження речей — це зупинка, навіть якщо вона триває понад 5 хвилин. 8 хвилин з візком — теж зупинка.","Поки висаджуєш пасажира — це зупинка, хоч скільки часу йде."],
"s45":["Якщо відходиш у своїх справах довше ніж на 5 хвилин, а не висаджуєш пасажирів чи розвантажуєш речі, — це вже стоянка.","Понад 5 хвилин і не заради пасажирів чи вантажу — це вже стоянка."],
"s46":["Ставити на дорогу конуси чи інші предмети, щоб «застовпити» місце, заборонено — дорога спільна для всіх.","Конус — не бронь. Місце на дорозі не резервують."],
"s47":["Предмети, що заважають проїзду, на дорогу можна ставити лише з поважних причин: під час оформлення ДТП, дорожніх робіт або коли рух обмежують за законом.","Конуси на дорозі — для аварії чи ремонту, а не для твого паркомісця."],
"s48":["Якщо зламане авто стоїть там, де оглядовість менше 100 метрів, однієї аварійки замало — додатково виставляй знак аварійної зупинки.","Погано видно — мало блимати: став знак аварійної зупинки."],
"s49":["Ні, порушення немає. Ближче 10 метрів до переходу зупинятися можна, якщо пропускаєш пішохода, — саме цього правила й вимагають.","Стоїш, щоб пропустити пішохода, — правило 10 м тебе не стосується."],
"s50":["Так, можна. Правило «вночі лише на майданчику чи поза дорогою» діє тільки за містом. А аварійку на звичайній стоянці не вмикають.","Нічна заборона стоянки біля краю дороги — лише за містом."],
"s51":["У два ряди можна ставити лише вузький двоколісний транспорт. Мотоцикл із коляскою ширший, тому його ставлять в один ряд.","Коляска забирає місце — такий мотоцикл стоїть в один ряд, як авто."],
"s52":["Якщо в місті по дві смуги в кожен бік, зупинятися можна лише праворуч. Ліворуч — тільки на дорогах з однією смугою в кожен бік або на односторонніх.","Широка дорога — висаджуй лише праворуч."],
"s53":["Якщо на перехресті є перехід, 10 метрів заборони міряють від переходу. Від краю поперечної дороги рахують лише тоді, коли переходу немає.","Є зебра — міряй від неї."],
"s54":["Біля переїзду ближче 50 метрів заборонено лише стоянку, а зупинятися можна. Тож за 30 м до переїзду висадити пасажира можна, а біля переходу чи зупинки автобуса — ні.","Переїзд забороняє стояти, а не зупинитися: 50 м — межа для стоянки."],
"s55":["Ні. Заборона зупинки на 10 метрів діє і перед переходом, і після нього, тож 5 м після переходу — замало.","10 м — з обох боків зебри, як у дзеркалі."],
"c1":["На перехресті рівнозначних доріг без кругового руху й трамваїв пропускаєш того, хто наближається праворуч.","«Перешкода справа»: хто праворуч — той і перший."],
"c2":["Повертаючи ліворуч, ти перетинаєш шлях зустрічним, тому пропускаєш тих, хто їде назустріч прямо або праворуч.","Ліворуч повертаєш — зустрічних прямо пропускаєш."],
"c3":["З другорядної дороги ти пропускаєш усіх, хто їде головною, — куди б вони не прямували: прямо, ліворуч чи праворуч.","Другорядна — значить ти другий у черзі для всіх на головній."],
"c4":["Зелений дозволяє рух, але не дає переваги над зустрічними. Повертаючи ліворуч, пропусти тих, хто їде назустріч прямо чи праворуч.","Зелений — це «можна», а не «перший»."],
"c5":["Повертаючи праворуч, пропусти пішоходів, які переходять дорогу, на яку ти заїжджаєш, — навіть якщо тобі горить зелений.","Повертаєш — пішохода пропускаєш."],
"c6":["Навіть на зелений не виїжджай на перехрестя, якщо за ним затор і ти там застрягнеш, — перекриєш шлях іншим.","Нема куди виїхати — не заїжджай."],
"c7":["Коли світлофор працює у звичайному режимі, слухай його, а знаки пріоритету не враховуй — вони для випадків, коли світлофор вимкнений або миготить жовтим.","Світлофор працює — знаки пріоритету відпочивають."],
"c8":["Регульоване перехрестя — те, де порядок проїзду визначає світлофор або регулювальник. Самі лише знаки пріоритету не роблять його регульованим.","Регулює той, хто світить або махає жезлом."],
"c9":["Якщо світлофор не працює і регулювальника немає, їдь як через звичайне нерегульоване перехрестя: дивись на знаки пріоритету і правила черговості.","Світлофор згас — вмикаються знаки."],
"c10":["Миготливий жовтий означає, що світлофор не керує рухом. Тоді діє знак «Дати дорогу» — пропусти тих, хто їде головною.","Жовтий блимає — керує знак. «Дати дорогу» — значить чекаєш."],
"c11":["Якщо на перехресті працює регулювальник, перехрестя регульоване, навіть коли світлофор миготить жовтим. Їдь за сигналами регулювальника.","Є регулювальник — перехрестя регульоване, хоч як блимає світлофор."],
"c12":["Коли світлофор працює, знак головної дороги не діє. Повертаючи ліворуч на зелений, ти пропускаєш зустрічне авто, що їде прямо.","Світлофор працює — «головна» не рятує: ліворуч пропускаєш зустрічних."],
"c13":["Повертаючи, пропусти велосипедиста, який їде прямо в тому ж напрямку, — інакше переріжеш йому шлях.","Повертаєш праворуч — глянь у праве дзеркало: велосипедист, що їде прямо, перший."],
"c14":["Повертаючи на будь-якому перехресті, пропусти пішоходів, що переходять дорогу, куди ти повертаєш, і велосипедистів, що їдуть прямо в той самий бік.","Поворот — дві перевірки: пішоходи попереду, велосипедисти збоку."],
"c15":["Навіть якщо переходу не намальовано, пішоходи, які переходять дорогу, куди ти повертаєш, мають перевагу. Пропусти їх.","Немає зебри — є пішохід. Повертаєш — пропускаєш."],
"c16":["Якщо треба когось пропустити, а перед перехрестям є стоп-лінія, зупиняйся саме перед нею, а не за нею.","Стоп-лінія — твій поріг: поки чекаєш, не переступай."],
"c17":["Без розмітки й світлофора зупиняйся перед краєм дороги, яку перетинаєш, але так, щоб не стояти на шляху пішоходів.","Немає лінії — твоя межа край поперечної дороги. Пішоходів не перекривай."],
"c18":["Якщо стоп-лінії немає, орієнтуйся на світлофор: зупиняйся перед ним так, щоб добре бачити його сигнали.","Немає лінії — стань так, щоб бачити світлофор, а не під ним."],
"c19":["Навіть на головній дорозі не виїжджай на перехрестя, якщо за ним затор: застрягнеш посередині й заблокуєш і машини, і пішоходів.","Головна дорога не дає права закупорити перехрестя."],
"c20":["Заборона виїжджати в затор діє на всіх перехрестях — і зі світлофором, і без нього, навіть коли тобі горить зелений.","Затор за перехрестям — чекаєш перед ним, хоч зелений, хоч ні."],
"c21":["Зелений для тебе ще не означає, що перехрестя вільне. Спершу дай доїхати тим, хто вже на ньому, а тоді рушай.","Зелений загорівся — спершу дай іншим доїхати."],
"c22":["Коли загорівся зелений, дай завершити рух і машинам, які ще на перехресті, і пішоходам, які закінчують перехід. Тільки потім рушай.","Зелений — не старт: спершу всі, хто не встиг, мають завершити."],
"c23":["На рівнозначному перехресті без світлофора трамвай має перевагу над машинами, куди б він не їхав: прямо, ліворуч чи праворуч.","Рівнозначне перехрестя — трамвай перший, хоч куди повертає."],
"c24":["Розвертаючись на зелений, ти поступаєшся зустрічним, що їдуть прямо або повертають праворуч, — так само, як при повороті ліворуч.","Розворот — це лівий поворот «на максимум»: зустрічних пропускаєш."],
"c25":["Повертаючи ліворуч на зелений, пропусти трамвай, що їде прямо в тому ж напрямку: ти перетинаєш його колію.","Ліворуч через рейки — спершу трамвай."],
"c26":["Ти їдеш прямо, тож перевага твоя: той, хто на зелений повертає ліворуч, має пропустити тебе.","Хто на зелений повертає ліворуч, той і чекає. Ти їдеш прямо — проїжджаєш."],
"c27":["Між трамваями діє те саме правило: той, хто на зелений повертає ліворуч, пропускає зустрічного, що їде прямо.","Правило лівого повороту однакове для всіх — навіть для трамваїв."],
"c28":["Якщо зелений дозволяє рух і тобі, і трамваю, перевага в трамвая, куди б він не повертав. Тож пропусти його, навіть їдучи прямо.","Спільний зелений із трамваєм — трамвай перший, хоч куди повертає."],
"c29":["Якщо регулювальник дозволяє рух і трамваю, і машинам одночасно, першим їде трамвай — незалежно від того, куди він повертає.","Один сигнал на двох — трамвай попереду."],
"c30":["В'їхавши на перехрестя на зелений, завершуй рух у потрібному напрямку. Світлофор на виїзді без стоп-лінії чи знака перед ним тебе не зупиняє.","В'їзд на зелений — виїзд вільний, якщо перед світлофором на виїзді немає стоп-лінії чи знака."],
"c31":["Якщо перед наступним світлофором є стоп-лінія, він теж для тебе діє. Горить червоний — зупиняйся перед лінією.","Є стоп-лінія перед світлофором — виконуй і його сигнал."],
"c32":["Якщо ти вже на перехресті й чекаєш, щоб повернути ліворуч, а загорівся червоний, — завершуй поворот. Інші мають дати тобі виїхати.","Хто вже на перехресті — той його і звільняє."],
"c33":["Стрілка в додатковій секції разом із жовтим дозволяє повернути, але не дає переваги. Пропусти тих, хто їде з інших напрямків.","Стрілка поруч із жовтим чи червоним — дозвіл, а не перевага."],
"c34":["Повертати праворуч на червоний за зеленою стрілкою на табличці можна лише з крайньої правої смуги.","Стрілка праворуч — тільки з крайньої правої."],
"c35":["Табличка зі стрілкою дозволяє повернути на червоний, але тільки якщо пропустиш усіх: і машини, і пішоходів з інших напрямків.","На червоний повертаєш — усім іншим поступаєшся."],
"c36":["Велосипед — теж транспорт. Тож, виїжджаючи з другорядної дороги, ти пропускаєш і велосипедиста на головній.","Велосипед на головній — те саме, що авто на головній: пропускаєш."],
"c37":["Якщо стоятимеш на червоний, черга позаду не зможе поїхати за своєю стрілкою — ти їй заважаєш. Тож рушаєш за стрілкою праворуч, навіть якщо планувалося прямо.","Не будь пробкою: заважаєш тим, хто позаду, — їдь за стрілкою сам."],
"c38":["Їхати за стрілкою обов’язково лише тоді, коли твоя зупинка заважає машинам позаду. Позаду нікого — спокійно чекаєш зеленого, щоб їхати прямо.","Нікого позаду — нікому не заважаєш, тож і за стрілкою їхати не мусиш."],
"c39":["З другорядної ти пропускаєш усіх, хто їде головною, хоч куди б вони збиралися. Увімкнений покажчик на це не впливає.","Другорядна — завжди друга: куди б не їхала машина на головній, вона перша."],
"c40":["Дати дорогу означає не виїжджати, якщо через тебе тому, хто на головній, доведеться пригальмувати чи об’їжджати. Те, що він ще далеко, не виправдання.","Правило ноги: якщо водієві на головній доведеться торкнутися гальма через тебе — стій."],
"c41":["Авто з другорядної чекає, поки проїдуть усі з головної. А між вами двома на головній діє звичне правило: повертаючи ліворуч, пропускаєш зустрічного, що їде прямо.","Спершу головна, потім другорядна. А на головній лівий поворот пропускає зустрічного."],
"c42":["Цей знак означає, що ти на головній дорозі. Правило «пропусти того, хто справа» діє лише на рівнозначних, а тут авто справа їде другорядною і мусить тебе пропустити.","Жовтий ромб — ти на головній: ті, хто з другорядних, чекають, навіть якщо вони справа."],
"c43":["Трамвай має перевагу лише на рівнозначних дорогах. Якщо він їде другорядною, то, як і всі, пропускає тих, хто на головній.","Головна сильніша за рейки: з другорядної навіть трамвай поступається."],
"c44":["Знак попереджає про перехрестя рівнозначних доріг. На такому перехресті без світлофора трамвай їде першим, звідки б він не наближався, навіть зліва.","Рівнозначні дороги — у трамвая козир: зліва чи справа, він перший."],
"c45":["На рівнозначному перехресті трамвай проїжджає першим. Далі ти, бо для легковика зліва ти справа, і він мусить тебе пропустити.","Спершу рейки, потім той, хто справа: трамвай, ти, легковик."],
"c46":["Між собою трамваї рівні, тому діє звичне правило: першим проїжджає той, хто для іншого праворуч.","Трамвай проти трамвая — як авто проти авто: правий перший."],
"c47":["На нерегульованому колі зі знаком 4.10 першими їдуть ті, хто вже на ньому. Ти лише в’їжджаєш, тож пропускаєш авто, яке вже рухається по колу.","Коло — як карусель: спершу ті, хто вже катається, потім нові."],
"c48":["Перевага трамвая на нерегульованих перехрестях не працює там, де круговий рух. На колі першими їдуть ті, хто вже по ньому рухається, тобто ти.","На колі навіть трамвай чекає: хто вже крутиться — той перший."],
"c49":["Звичне правило «пропусти того, хто справа» має виняток — коло. Там першими їдуть ті, хто вже рухається по колу, а ті, хто в’їжджає, чекають.","Коло ламає правило правої руки: хто на колі — той і перший."],
"c50":["Те, що твоя дорога йде далі, а сусідня лише примикає, переваги не дає. Дороги рівнозначні — значить, пропускаєш того, хто справа.","Буква Т прав не дає: хто справа — той перший."],
"c51":["На рівнозначному перехресті перевага в того, хто справа. Для авто зліва ти саме справа, тож воно пропускає тебе, хоч і їде прямо.","Ти в нього справа — ти й перший. Куди хто їде, тут не важить."],
"c52":["Перш ніж повернути ліворуч, пропусти трамвай, що їде в той самий бік. Те, що ти справа від нього, тут нічого не дає.","Повертаєш ліворуч — попутний трамвай проїжджає першим."],
"c53":["Повертаючи ліворуч, ти пропускаєш зустрічних, що їдуть прямо або праворуч. Навіть якщо ви звертаєте на одну дорогу, першим туди заїжджає зустрічне авто.","Лівий поворот — найдовший шлях, тому він і чекає найдовше."],
"c54":["Б пропускає А, бо А для нього праворуч. Ти пропускаєш обох: Б — бо він справа від тебе, А — бо він зустрічний, а ти повертаєш ліворуч. Тож твоя черга остання.","Лівий поворот — у хвості черги: спершу всі, хто має перевагу, потім ти."],
"c55":["Коли головна дорога на перехресті повертає, ті, хто їде нею, між собою роз’їжджаються так, ніби дороги рівнозначні.","Головна зігнулася — між своїми, як на рівнозначних."],
"c56":["Ви обидва на головній, а вона повертає, тож між собою ви як на рівнозначному перехресті. А там пропускають того, хто справа.","Обидва на головній — рахуй, як на рівних: правий перший."],
"c57":["Хоч ти й повертаєш ліворуч, зустрічне авто їде другорядною. А з другорядної пропускають усіх, хто на головній, тож воно чекає на тебе.","Спершу дивися, хто на якій дорозі: другорядна чекає завжди, навіть зустрічна."],
"c58":["Ви обидва на другорядних, тож між собою — як на рівнозначному перехресті. А там першим їде той, хто справа.","Двоє з другорядних — рівні між собою: перший той, хто праворуч."],
"c59":["Якщо через темряву, сніг чи бруд не зрозуміти, яке під колесами покриття, а знаків немає, вважай свою дорогу другорядною і пропускай інших.","Сумніваєшся в дорозі — вважай її другорядною."],
"c60":["Дорога з покриттям вважається головною щодо ґрунтової. Тож з ґрунтовки ти пропускаєш усіх на асфальті, навіть якщо вони зліва.","Асфальт старший за ґрунт: з ґрунтовки — чекай."],
"c61":["Шматок асфальту перед самим перехрестям не робить ґрунтовку рівною дорозі з покриттям. Вона й далі другорядна, тож ти поступаєшся.","Асфальтова латка не перетворює ґрунтовку на головну."],
"c62":["Смуга для автобусів і тролейбусів — не для звичайних легковиків. Крім маршрутних, нею можуть їхати таксі, мопеди, мотоцикли без бокового причепа та велосипедисти.","Список гостей смуги: таксі, мопед, мотоцикл без причепа, велосипед. Решта — повз."],
"c63":["Звичайним мотоциклам на смугу для маршрутних можна, а з боковим причепом — уже ні. Так само заборонено мотоколяскам і триколісним.","Мотоцикл із причепом-коляскою — уже не гість на смузі для автобусів."],
"c64":["Зупинятися на смузі для маршрутних іншим машинам заборонено. Заїхати туди, щоб висадити пасажира, можна лише там, де смугу відділяє переривчаста лінія, а тут суцільна.","Суцільна лінія — суцільна заборона: на автобусну смугу навіть на хвилинку не можна."],
"c65":["Переривчаста лінія — це «двері» на смугу для маршрутних. Через неї можна заїхати на цю смугу й повернути з неї праворуч.","Пунктир — пропуск: можна заїхати на автобусну смугу, щоб звернути праворуч."],
"c66":["Де смугу для маршрутних відділяє переривчаста лінія, на неї можна заїхати, щоб виїхати на дорогу або посадити чи висадити пасажирів біля правого краю. Випереджати нею потік не можна.","Пунктир пускає на смугу лише у справах біля краю: поворот, виїзд, посадка-висадка."],
"c67":["Там, де рейки перетинають твою смугу поза перехрестям, трамвай їде першим. Виняток один — коли він виїжджає з депо.","Поза перехрестям рейки головні: бачиш трамвай — пропускай."],
"c68":["Поза перехрестям трамвай зазвичай має перевагу там, де колії перетинають дорогу. Але коли він виїжджає з депо, ця перевага не діє.","З депо трамвай виїжджає «без корони» — там перевага не його."],
"c69":["У населеному пункті автобус, що рушає від зупинки з «кармана», треба випустити. Скидаєш швидкість, а якщо потрібно, зупиняєшся й даєш йому виїхати.","Автобус у «кармані» — не тримай його там: пригальмуй і випусти."],
"c70":["Навіть коли інші мають дати йому рушити, водій тролейбуса не їде навмання. Він сам мусить подбати, щоб не сталося аварії.","Перевага — не страховка: і той, кого пропускають, теж стежить, щоб не було ДТП."],
"r1":["Пішохід на нерегульованому переході має перевагу над машиною. Скидаєш швидкість і за потреби зупиняєшся, щоб він спокійно перейшов.","Зебра без світлофора — пішохід там господар."],
"r2":["Людину з білою тростиною, спрямованою вперед, пропускаєш будь-де, навіть поза переходом. Вона може не бачити твого авто.","Біла тростина вперед — це «стоп» для тебе в будь-якому місці."],
"r3":["Діти можуть раптово вибігти з-за автобуса. Тож скидаєш швидкість і готуєшся зупинитися, щоб їх пропустити.","Табличка «Діти» — нога над гальмом: малеча вибігає без попередження."],
"r4":["Якщо немає ні стоп-лінії, ні знака, ні шлагбаума, орієнтиром стає сам світлофор. Зупиняєшся перед ним так, щоб бачити його сигнали.","Немає лінії — є світлофор: стій перед ним і дивись на нього."],
"r5":["Два червоні вогні, що блимають по черзі, означають: наближається потяг. Їхати через переїзд не можна — стоїш і чекаєш.","Два червоні «підморгують» по черзі — потяг близько, стій."],
"r6":["Швидка поспішає рятувати людей, тож звільняєш їй шлях. Але робиш це спокійно, щоб не створити небезпеки іншим, — без різкого гальмування на місці.","Синій маячок і сирена позаду — розступись, як море, але плавно."],
"r7":["Оранжевий маячок на дорожній техніці лише попереджає: обережно, тут щось відбувається. Переваги в русі він не дає.","Оранжевий — як знак оклику: увага, а не «пропусти мене»."],
"r8":["Відступати від деяких правил водій оперативного авто може лише з увімкненим синім чи червоним маячком і спецсигналом. І навіть тоді він мусить подбати про безпеку руху.","Синій чи червоний маячок плюс спецсигнал — і лише за умови безпеки. Оранжевий не рахується."],
"r9":["Оперативне авто може відступати від деяких правил регулювання, але не від сигналів регулювальника. Його жести обов’язкові навіть для машини з сиреною.","Регулювальник головніший за сирену: його слухають усі."],
"r10":["Синій разом із червоним маячком вимагає більшого, ніж просто пропустити. Ти мусиш зупинитися біля правого краю дороги або на правому узбіччі.","Додався червоний — значить, «стоп»: з’їжджай праворуч і стій."],
"r11":["Якщо дорогу ділить розділювальна смуга, зупинятися біля правого краю мають лише ті, хто їде з цим авто в один бік. Зустрічним зупинятися не треба.","Розділювальна смуга — як стіна: зупиняється лише той бік, де їде машина з маячками."],
"r12":["Усі машини колони, яку супроводжує авто з маячками, їдуть з увімкненим ближнім світлом. Так колону легко помітити.","Колона світиться ближнім — щоб усі бачили, хто в ній."],
"r13":["Якщо з громіздкою річчю на тротуарі людина заважає іншим, вона може йти краєм дороги. Але тільки в один ряд, а не поруч з кимось.","Велика ноша — на край дороги, але по одному."],
"r14":["Колону відкриває авто з синім і червоним маячками, а закриває — із зеленим. Поки не проїде це останнє авто, стоїш.","Зелений маячок — як зелене світло: проїхав останній — можна рушати."],
"r15":["Таку колону не можна обганяти, займати місце в ній чи їхати сусідньою смугою пліч-о-пліч з нею. Колона рухається у вільному коридорі.","Колона — не попутник: їхати поруч у її темпі заборонено."],
"r16":["Учасник ДТП — не лише водій. Пішохід, причетний до аварії, допомагає потерпілим, повідомляє поліцію і чекає її на місці.","Причетний — значить залишайся: допоможи, подзвони, дочекайся."],
"r17":["Повз авто з синім маячком, що стоїть, проїжджаєш не швидше 40 км/год. Сирена для цього не потрібна — досить маячка.","Синій маячок стоїть — ти їдеш до 40."],
"r18":["Якщо біля такого авто регулювальник тебе зупинив, рушаєш лише тоді, коли він дозволить. Вільна дорога чи вимкнений маячок нічого не змінюють.","Зупинив регулювальник — він і відпускає."],
"r19":["Під час робіт дорожня техніка може не зважати на більшість знаків і розмітку. Але знаки пріоритету та знаки 3.21–3.23 обов’язкові й для неї.","Дорожникам можна майже все, крім знаків пріоритету та 3.21–3.23."],
"r20":["Щоб дати дорогу, не треба чекати сирени. Досить і одного увімкненого синього маячка, і лише спецсигналу.","Синій маячок або сирена — досить одного, щоб поступитися."],
"r21":["Почувши сирену чи побачивши маячок, пішохід не виходить на дорогу, навіть на зелений. А якщо вже йде нею — негайно її залишає.","Сирена гучніша за зелений: пішохід чекає на тротуарі."],
"r22":["Коли тротуару, доріжок і узбіччя немає, пішохід іде краєм дороги назустріч машинам. Так він бачить авто, що наближаються.","Іди так, щоб бачити фари, а не підставляти спину."],
"r23":["Без тротуару пішохід може йти велодоріжкою. Тримається правого боку й не заважає велосипедистам.","На велодоріжці пішохід — гість: правим боком і не на заваді."],
"r24":["Поза населеним пунктом пішохід іде узбіччям назустріч машинам, щоб бачити їх заздалегідь.","Пішохід за містом дивиться машинам в обличчя."],
"r25":["Хто веде велосипед, мопед чи мотоцикл узбіччям, рухається туди ж, куди й машини. Тобто разом з потоком, а не назустріч, як звичайний пішохід.","Колеса поруч — іди за потоком, як вони."],
"r26":["Світлоповертачі потрібні, коли темно або погано видно. Стрічка чи жилет відбивають світло фар, і водій вчасно помічає пішохода.","Темно чи погано видно — засвітись світлоповертачем."],
"r27":["Організована колона людей іде дорогою не більше ніж по четверо в ряду. Так вона не займає зайвої частини дороги.","Як коліс у легковика: у ряду колони не більше чотирьох."],
"r28":["Супровідники з червоними прапорцями йдуть попереду й позаду колони, на відстані 10–15 метрів, з лівого боку — того, що ближче до машин.","Прапорці ліворуч, спереду і ззаду — за 10–15 м від колони."],
"r29":["У темряві супровідник попереду несе білий ліхтар, а позаду — червоний. Як в авто: білі фари спереду, червоні вогні ззаду.","Колона — як машина: білий спереду, червоний ззаду."],
"r30":["Групу дітей можна вести узбіччям тільки вдень і лише з дорослими. У темряві так водити їх не можна.","Діти на узбіччі — лише вдень і з дорослими поруч."],
"r31":["Якщо поруч немає ні переходу, ні перехрестя, таку дорогу переходять під прямим кутом і там, де її добре видно в обидва боки.","Навскіс — довше на дорозі. Прямо поперек — і там, де видно обидва боки."],
"r32":["Через широку дорогу з чотирма й більше смугами або з розділювальною смугою поза переходом не переходять. Тут тільки пішохідний перехід.","Широка дорога чи розділювальна смуга посередині — тільки по переходу."],
"r33":["Не встигнувши перейти, пішохід не біжить назад і не йде далі на заборонний сигнал. Якщо острівця чи розділювальної лінії немає, він чекає на середині дороги.","Сигнал змінився посередині — там і чекай дозволу."],
"r34":["Де немає посадкового майданчика, на дорогу виходять лише з боку дверей і тільки коли трамвай уже зупинився. Бігти до трамвая, що під’їжджає, не можна.","Спершу трамвай стоїть, потім ти йдеш — і лише з боку дверей."],
"r35":["На автомагістралі пішоходам ходити заборонено. Виняток — пішохідні доріжки, місця стоянки й відпочинку.","Автомагістраль — для коліс, а ноги лише на доріжці, стоянці чи в місці відпочинку."],
"r36":["Людина в кріслі колісному, що рухається зі швидкістю пішохода, на позначеному переході має перевагу так само, як пішохід. Ти її пропускаєш.","Крісло колісне на зебрі — той самий пішохід: пропускай."],
"r37":["Краєм дороги крісло колісне їде разом з потоком у правій крайній смузі, як велосипедист, а не назустріч, як пішохід.","На проїзній частині крісло колісне — як велосипед: праворуч і за потоком."],
"r38":["Крісло колісне — для однієї людини. Тож возити в ньому пасажирів і чіпляти до нього причіп заборонено.","Одне крісло — одна людина, без пасажирів і без причепа."],
"r39":["Якщо світлофор на переході блимає жовтим, він фактично не керує рухом. Такий перехід — нерегульований, і пішоходів на ньому треба пропускати.","Жовтий блимає — ніби світлофора немає: перехід нерегульований."],
"r40":["Твій зелений не означає, що можна їхати на людей. Пішоходи, які ще закінчують перехід, мають право спокійно дійти, а ти чекаєш.","Зелений — дозвіл рушити, а не наказ розганяти пішоходів."],
"r41":["Люди на острівці безпеки стоять зовсім поруч із потоком. Проїжджай повз них, залишаючи безпечний проміжок.","Острівець безпеки — не край дороги: дай людям місце, не притирайся."],
"r42":["Сусідня машина, найімовірніше, пропускає пішохода, якого ти за нею не бачиш. Тож пригальмовуєш і за потреби зупиняєшся, доки не переконаєшся, що на переході нікого.","Сусід став перед зеброю — значить, щось бачить. Гальмуй і ти."],
"r43":["Якщо за переходом затор і ти застрягнеш просто на «зебрі», краще почекати перед нею. Стоячи на переході, ти загородиш шлях пішоходам.","Зебра — не парковка: немає місця за нею — стій перед нею."],
"r44":["Рука вгору від шкільного патруля чи супровідника дітей означає, що треба зупинитися. Стаєш перед переходом і пропускаєш дітей, хоч це й не регулювальник.","Рука вгору в жилеті біля зебри — діти йдуть, ти стоїш."],
"r45":["Коли люди виходять з трамвая просто на дорогу, ти зупиняєшся й даєш їм пройти до тротуару чи до трамвая. Протискатися між ними й трамваєм не можна.","Трамвай відчинив двері на дорогу — дорога на хвилину стала тротуаром."],
"r46":["Рушати можна, лише коли всі пішоходи зійшли з дороги і двері трамвая зачинилися. Поки двері відчинені, хтось ще може вийти.","Двері зачинилися й дорога порожня — тоді й рушай."],
"r47":["Піднятий шлагбаум без заборонних сигналів — ще не гарантія. Перед коліями сам переконайся, що не наближається поїзд, локомотив чи дрезина.","Шлагбаум піднятий, а голова все одно крутиться: подивись, чи немає поїзда."],
"r48":["Коли на переїзді немає ні шлагбаума, ні світлофора, ні стоп-лінії, ні знака, зупиняєшся щонайменше за 10 метрів до найближчої рейки.","Нічого не підказує — тримай 10 м до рейки."],
"r49":["Опущений шлагбаум і є твоя межа. Зупиняєшся перед ним так, щоб бачити сигнали, і чекаєш.","Шлагбаум опущено — стій перед ним, а не за ним."],
"r50":["Якщо розмітка чи знаки не показують, скільки тут смуг, через переїзд їдуть тільки в один ряд. Навіть на широкій дорозі — без «у два ряди».","Смуги не розмічені — через рейки лише одним рядом, як вагони потяга."],
"r51":["Перетинати колії на машині можна лише на залізничних переїздах. Навіть якщо рейки врівень з дорогою і потяга не видно, деінде цього робити не можна.","Рейки перетинаєш тільки там, де є переїзд, — інших «бродів» немає."],
"r52":["На переїзді черговий, який стоїть до тебе грудьми з руками в сторони, забороняє рух. Не плутай із регулювальником на перехресті: тут цей жест означає «стоп».","Руки в сторони на переїзді — це шлагбаум із людини: стоп."],
"r53":["Рух через переїзд заборонено не лише коли шлагбаум уже опущений, а й коли він тільки почав опускатися. Не намагайся проскочити — зупиняйся.","Шлагбаум пішов донизу — нога пішла на гальмо."],
"r54":["Червоний сигнал світлофора чи звуковий сигнал на переїзді важливіші за шлагбаум. Навіть якщо він піднятий, їхати не можна.","Блимає червоне — шлагбаум не рахується, рахується світлофор."],
"r55":["Якщо через затор доведеться стати просто на переїзді, заїжджати туди не можна. Чекаєш перед ним, доки за переїздом звільниться місце.","На рейках не стоять навіть хвилину: немає місця за переїздом — чекай перед ним."],
"r56":["Бачиш потяг, що наближається до переїзду, — зупиняєшся й пропускаєш його. Відстань і швидкість поїзда легко недооцінити.","Потяг у полі зору — переїзд закритий, навіть без шлагбаума."],
"r57":["Трактори, дорожні й будівельні машини перетинають переїзд тільки в транспортному стані, тобто складеними для поїздки, а не в робочому положенні.","Через колії — по-дорожньому, а не по-робочому."],
"r58":["Коли переїзд закритий, об’їжджати чергу перед ним заборонено, навіть якщо зустрічна смуга порожня. Стаєш у кінець і чекаєш.","Перед закритим переїздом черга недоторканна — тільки в хвіст."],
"r59":["Якщо машина заглухла на рейках, головне — люди. Спершу висаджуєш усіх, а потім робиш усе, щоб звільнити переїзд.","Авто стало на рейках — спершу люди, потім залізо."],
"r60":["Двох людей відправляють уздовж колій у різні боки, щонайменше на 1000 метрів. Так машиніст побачить сигнал зупинки заздалегідь.","Потяг гальмує довго, тож попереджають далеко: по 1000 м у кожен бік."],
"r61":["Якщо можна відправити лише одну людину, на одноколійному переїзді її посилають туди, де колію гірше видно. Звідти поїзд з’явиться найнесподіваніше.","Одна людина — туди, де гірше видно: там небезпека ховається."],
"r62":["Коли поїзд уже видно, не чекай біля авто. Біжи йому назустріч і подавай сигнал зупинки, щоб машиніст почав гальмувати якомога раніше.","Потяг видно — біжи до нього, а не від нього, і подавай сигнал."],
"r63":["Щоб машиніст зупинився, роби рукою кола, тримаючи щось помітне: вдень яскраву тканину, у темряві ліхтар чи факел.","Крути коло рукою з чимось яскравим — це «стоп» для машиніста."],
"r64":["Сигнал загальної тривоги звучить серіями: один довгий гудок і три короткі. Так його не сплутаєш зі звичайним сигналом.","Ту-у-у, ту-ту-ту: один довгий і три короткі — тривога."],
"r65":["Стадо через переїзд переганяють лише тоді, коли погоничів достатньо, але щонайменше троє. Менше — не можна.","Стадо через рейки — мінімум трійка погоничів."],
"b1":["Їздити дорогою на велосипеді можна з 14 років. З цього ж віку дозволено керувати возом і переганяти тварин.","Паспорт у 14 — і велосипед на дорогу теж з 14."],
"b2":["Світлоповертачі на велосипеді — як вогні в авто: спереду білі, по боках оранжеві, ззаду червоні. Так водії бачать велосипед з будь-якого боку.","Як у машини: білий ніс, оранжеві боки, червоний хвіст."],
"b3":["Гальмо, щоб вчасно зупинитися, і дзвінок, щоб попередити інших, мають бути справні. Без дзеркала чи підніжки їхати можна, а з несправним гальмом чи сигналом — ні.","Без «стоп» і без «дзень» — нікуди не їдь."],
"b4":["Велоколону розбивають на групи до 10 людей, а між групами тримають 80–100 метрів. Усередині групи їдуть один за одним, щоб не заважати іншим.","До 10 у групі, 80–100 м між групами — як вагончики з проміжками."],
"b5":["Поза перехрестям велосипедист, що перетинає дорогу, пропускає машини, які нею їдуть. Перевага в тих, хто на дорозі.","Велодоріжка «врізається» в дорогу — велосипедист чекає."],
"b6":["Якщо поряд є велодоріжка, їхати проїзною частиною на велосипеді заборонено. Велосипед — на свою доріжку, швидкість тут не має значення.","Є велодоріжка — там і місце велосипеда. Дорога — для машин."],
"b7":["Тротуаром на велосипеді можна їздити лише малечі до 7 років на дитячих велосипедах і під наглядом дорослих. Усім іншим — ні.","Тротуар — для дитячих велосипедів: до 7 і з дорослим поруч."],
"b8":["Дітей до 7 років можна возити на велосипеді, але лише на окремому додатковому сидінні з надійно закріпленими підніжками. На рамі — не можна.","Малюк — тільки у своєму сидінні з підніжками, не на рамі."],
"b9":["Вантаж на велосипеді возити можна, якщо він не заважає керувати й нікому не створює перешкод. А чіплятися за машини, тягнути інший велосипед і їхати без рук — ні.","Сумка — так, трюки — ні: руки на кермі, ні за кого не чіпляйся."],
"b10":["Мопед — це двоколісний транспорт з маленьким двигуном: до 50 куб. см або електромотором до 4 кВт. Від 50 куб. см — це вже мотоцикл.","Мопед — «до 50», мотоцикл — «від 50»."],
"b11":["Велосмуга — це частина самої дороги, виділена для велосипедів. Велодоріжка — окремий шлях поза проїзною частиною.","Смуга — серед машин (с–с), доріжка — далі від дороги (д–д)."],
"b12":["Віз у темряві світиться як маленьке авто: білий ліхтар спереду, червоний ззаду. Обидва — з лівого боку воза, ближче до потоку машин.","Ліхтарі воза — зліва, лицем до машин: білий уперед, червоний назад."],
"b13":["Коли з другорядної дороги погано видно, візник не виїжджає навмання, сидячи на возі. Він веде тварину за вуздечку чи повід, щоб контролювати кожен крок.","Погано видно — візник іде поруч і веде тварину за вуздечку."],
"b14":["Стадо дорогою переганяють лише вдень. У темряві чи за поганої видимості тварин важко помітити, тому переганяти їх заборонено.","Стадо ходить дорогою, поки світить сонце."],
"b15":["На державних трасах рух швидкий, і повільний віз там небезпечний. Тож якщо є інша дорога, віз їде дорогами місцевого значення.","Віз — місцевий житель: його дороги місцеві, а не державні."],
"l1":["Поза населеними пунктами вдень ходові вогні чи ближнє світло мають горіти завжди, незалежно від пори року. Сезонного правила в чинних ПДР немає.","За містом фари вдень — і взимку, і влітку: світло цілий рік."],
"l2":["Побачиш зустрічне авто — перемикай дальнє на ближнє заздалегідь, щонайменше за 250 метрів, щоб не засліпити водія.","Дальнє світло б’є далеко, тож і вимикати його треба здалеку — за 250 м."],
"l3":["Коли тебе засліпило, дороги не видно, тож перестроюватися не можна. Вмикаєш аварійку, тримаєшся своєї смуги, скидаєш швидкість і зупиняєшся.","Засліпило — аварійка, своя смуга, гальмо. Нічого не бачиш — нікуди не звертай."],
"l4":["У населеному пункті знак аварійної зупинки ставлять щонайменше за 20 метрів від авто. Поза ним — не ближче 40 м.","Місто — 20, траса — 40: за містом удвічі далі."],
"l5":["Гнучкий трос для буксирування має бути завдовжки від 4 до 6 метрів. А жорстка зчіпка — не довша за 4 м.","Жорстка — до 4 м, гнучкий трос — від 4 до 6: трос починається там, де жорстка закінчується."],
"l6":["На ожеледиці авто на тросі легко заносить. Тому в ожеледицю буксирують лише на жорсткій зчіпці або частковим навантаженням.","Лід і трос — погана пара: на слизькому тільки жорстка зчіпка."],
"l7":["Під час буксирування не можна їхати швидше за 50 км/год. Дві зчеплені машини гальмують і повертають гірше, ніж одна.","Буксир — не перегони: максимум 50."],
"l8":["У місті клаксон — не для привітань і не щоб підігнати повільного водія. Сигналити можна лише тоді, коли інакше не уникнути аварії.","Клаксон у місті — кнопка «рятувати», а не «привіт»."],
"l9":["Увімкнене вдень ближнє світло — теж попереджувальний сигнал: воно ніби каже іншим «я тут». Габарити на стоянці й задній протитуманний до цього списку не входять.","Ближнє вдень — як голос: «Увага, я їду!»"],
"l10":["Покажчик вмикають перед початком руху завжди, навіть коли поруч нікого не видно. Когось легко не помітити, а сигнал попередить.","Рушаєш — блимаєш. Порожньо навколо чи ні, не важливо."],
"l11":["Ліворуч показують лівою рукою, просто витягнутою вбік. Якщо зручніше правою — витягуєш її вбік і згинаєш у лікті вгору.","Ліва рука — ліворуч прямо, права — ліворуч «гачком» угору."],
"l12":["Якщо стоп-сигнали не працюють, про гальмування попереджають піднятою вгору рукою — лівою чи правою, як зручніше.","Рука вгору — живий стоп-сигнал."],
"l13":["Покажчик вмикають заздалегідь: у населеному пункті щонайменше за 50–100 метрів до маневру, поза ним — за 150–200 м.","Місто — 50–100, траса — 150–200: що швидше їдеш, то раніше блимаєш."],
"l14":["Покажчик лише повідомляє про твій намір, а не дає права. Перестроюватися можна тільки тоді, коли нікому не заважаєш.","Покажчик — це прохання, а не перепустка."],
"l15":["Покажчик вимикають одразу після маневру. Якщо він блимає далі, інші думатимуть, що ти ще збираєшся повертати.","Маневр скінчився — і блимання скінчилося."],
"l16":["Увімкнеш покажчик до перехрестя — інші подумають, що ти повертаєш праворуч. Тож проїжджаєш перехрестя і лише тоді вмикаєш його, щоб зупинитися.","Сигнал має бути зрозумілим: спершу перехрестя, потім покажчик."],
"l17":["Попередити водія, якого обганяєш, можна перемиканням фар. А поза населеним пунктом — ще й клаксоном.","За містом можна і блимнути, і бібікнути."],
"l18":["Дальнім світлом можна попереджати, але не тоді, коли воно засліпить водія, зокрема через дзеркало заднього виду.","Попередити — так, засліпити — ні: дзеркало теж відбиває дальнє."],
"l19":["У тунелі навіть удень темно, тож ближнє світло там обов’язкове. Так тебе краще видно іншим.","Тунель — це маленька ніч: заїжджаєш — вмикаєш ближнє."],
"l20":["Широка сільгосптехніка займає багато дороги, тож удень вона мусить їхати з ближнім світлом. Межа — ширина понад 2,6 метра.","Техніка ширша за 2,6 м — фари горять і вдень."],
"l21":["Поза населеними пунктами вдень мають горіти денні ходові вогні. Немає їх в авто — вмикаєш ближнє світло, габаритів для цього мало.","Немає денних ходових — їх замінює ближнє."],
"l22":["У тумані, коли погано видно, можна ввімкнути дальнє світло або додати протитуманні фари. Головне — щоб це не засліплювало інших водіїв.","Погано видно — додай світла спереду, але не в очі іншим."],
"l23":["Хто тягне, той їде з ближнім світлом. А той, кого тягнуть, вмикає аварійку.","Тягач — ближнє, «на тросі» — аварійка: голова світить, хвіст блимає."],
"l24":["Зупинившись на вимогу поліцейського, вмикаєш аварійку. Вона показує іншим водіям, що твоє авто стоїть не просто так.","Поліція зупинила — аварійка заблимала."],
"l25":["Якщо їдеш з несправністю, з якою рух дозволений, вмикаєш аварійку. Так інші знають, що з твоїм авто щось не так.","Авто «кульгає» — хай блимає аварійкою."],
"l26":["Знак аварійної зупинки обов’язковий після ДТП, а також при вимушеній зупинці там, де хоча б в один бік видно менше ніж на 100 метрів.","ДТП чи погано видно (менше 100 м) — до аварійки додай знак."],
"l27":["Замість знака аварійної зупинки можна поставити миготливий червоний ліхтар. Його світло має бути добре видно навіть удень на сонці.","Червоний трикутник чи червоний миготливий ліхтар — обидва кажуть «тут аварія»."],
"l28":["Якщо аварійка на буксированому авто не працює, ззаду ставлять знак аварійної зупинки або миготливий червоний ліхтар.","Немає аварійки — її замінить знак чи червоний ліхтар ззаду."],
"l29":["Уночі фари вмикають завжди, навіть якщо вулиця яскраво освітлена ліхтарями. Габарити чи денні ходові вогні не замінюють ближнього або дальнього світла.","Ніч = фари. Скільки б не було ліхтарів, самих габаритів замало."],
"l30":["Причіп у темряві має бути помітним сам по собі, тож на ньому світяться габаритні ліхтарі. Фари тягача світять уперед і причіп ззаду не позначають.","Причіп — не тінь тягача: у темряві в нього свої габарити."],
"l31":["У густому тумані вдень можна їхати з самими протитуманними фарами замість ближнього світла: за поганої видимості правила це дозволяють.","Туман удень — протитуманки можуть працювати й без ближнього."],
"l32":["Уночі на неосвітленій дорозі самих протитуманок замало: вмикай їх тільки разом з ближнім або дальнім світлом.","Ніч без ліхтарів: протитуманки — лише в парі з фарами, не соло."],
"l33":["Дальнє світло сліпить не лише зустрічних: через дзеркала воно б’є в очі й водієві попереду. Якщо можеш засліпити попутного водія — перемикай на ближнє.","Їдеш за кимось — не світи йому в дзеркала дальнім."],
"l34":["Після засліплення рушай тільки тоді, коли очі знову нормально бачать. Те, що зустрічне авто вже проїхало, ще не означає, що зір відновився.","Рушаєш не за годинником, а за очима: зір відновився — можна їхати."],
"l35":["Якщо вночі довелося вимушено зупинитися на дорозі, вмикай і габарити (або стоянкові вогні), і аварійку. Одне без іншого не підходить.","Вимушена зупинка вночі — подвійний захист: габарити плюс аварійка."],
"l36":["Коли стоїш у тумані, до габаритів можна додати ближнє світло або протитуманні фари, а також задні протитуманні ліхтарі, щоб авто було добре видно.","Стоїш у тумані — додай світла: ближнє чи протитуманки спереду, протитуманні ліхтарі ззаду."],
"l37":["Без габаритів уночі авто на дорозі майже непомітне. Тож прибери його за межі дороги, а якщо не виходить — виставляй знак аварійної зупинки.","Не світишся — не стій на дорозі. Не можеш з’їхати — постав трикутник."],
"l38":["Фару-прожектор чи фару-шукач можуть вмикати лише водії оперативних служб під час службових завдань, і так, щоб нікого не засліпити. Звичайним водіям — не можна.","Прожектор — інструмент служб на завданні, а не тюнінг для всіх."],
"l39":["Задні протитуманні ліхтарі не можна підключати до стоп-сигналів: у них своє окреме призначення, і правила це прямо забороняють.","Протитуманка — для туману, стоп — для гальм. Не змішуй."],
"l40":["Знак автопоїзда світиться весь час, поки автопоїзд їде. А в темряві чи за поганої видимості його не вимикають і тоді, коли автопоїзд стоїть на дорозі.","Їде — знак горить завжди. Стоїть у темряві чи тумані — теж горить."],
"l41":["Задній протитуманний ліхтар вмикають тільки тоді, коли видимість справді погана, — і вдень, і вночі. Сама лише темрява чи дрібний дощ, коли все добре видно, — не привід.","Задня протитуманка реагує на видимість, а не на годинник."],
"l42":["Якщо до твого авто вже причеплений причіп, буксирувати ще й інше авто не можна. Буксирує тільки машина без причепа.","Один «хвіст» на машину: або причіп, або буксир."],
"l43":["Буксирувати можна трьома способами: на жорсткій зчіпці, на гнучкій (трос чи стрічка) або частково поставивши авто на платформу чи спеціальну опору.","Штанга, трос або платформа — ось і всі три способи буксирування."],
"l44":["Звичайний трос інші водії можуть не помітити, тож на ньому через кожен метр чіпляють сигнальні щитки чи прапорці. Не треба лише на тросі зі світлоповертальним покриттям.","Трос без світлоповертачів — прапорець на кожному метрі, щоб його не проґавили."],
"l45":["Трос не втримає буксироване авто від наїзду на тягач, тож воно має саме гальмувати й кермуватися. Тому справні мають бути і гальма, і кермо.","Трос тягне, але не гальмує: на гнучкій зчіпці потрібні і кермо, і гальма."],
"l46":["Авто на тросі саме не їде: за кермом має сидіти водій, який кермує й гальмує. Без водія можна лише на жорсткій зчіпці, що повторює траєкторію тягача.","Трос — не автопілот: за кермом буксированого авто завжди людина."],
"l47":["Немеханічний транспортний засіб буксирують лише на жорсткій зчіпці, яка змушує його точно йти слідом за тягачем на всіх поворотах. Трос чи інші способи не годяться.","Немеханічний — значить, лише жорстко: слід у слід за тягачем."],
"l48":["Якщо кермо не працює, авто не втримає напрямку ні на тросі, ні на штанзі. Тому його везуть, частково поставивши на платформу чи спеціальну опору.","Кермо не крутиться — авто їде частково на платформі, а не на зчіпці."],
"l49":["Перед буксируванням обидва водії домовляються, як подаватимуть один одному сигнали, особливо — як показати, що треба зупинитися.","Спершу домовтеся про сигнали, особливо про «стоп», — а вже потім трос."],
"l50":["У легковику, який буксирують, пасажири їхати можуть — легкове авто тут виняток. Заборона стосується інших буксированих ТЗ і кузова вантажівки, що буксирує.","Легковик на буксирі — пасажирам можна, він виняток із заборони."],
"l51":["Якщо в буксированого авто не працюють гальма, гальмувати доведеться тягачу за двох. Тому таке авто має бути щонайменше вдвічі легшим за того, хто його тягне.","Гальма зламані — буксироване авто не важче за половину тягача."],
"l52":["Зчеплені авто разом не можуть бути довшими за 22 м. Довжина до 30 м дозволена лише маршрутним ТЗ.","Два авто в зчепці — дві двійки: не довше 22 м."],
"l53":["Мопед, як і мотоцикл без бокового причепа чи велосипед, буксирувати заборонено: на двох колесах це надто небезпечно. Легковики й вантажівки буксирувати можна.","Двоколісний — значить, не на трос: мопед буксирувати не можна."],
"l54":["Тягнути одразу два авто заборонено. Виняток — лише коли такий порядок погоджено з уповноваженим підрозділом Національної поліції.","Один тягач — один буксир. Більше — лише з погодження поліції."],
"l55":["Автобусам буксирувати заборонено взагалі — навіть порожнім і на жорсткій зчіпці. Автобус возить людей, а не тягає машини.","Автобус — для людей, а не для тросів."],
"k1":["Пасажирів у легковику може бути стільки, скільки в ньому передбачено місць для сидіння. «Ще одна дитина на коліна» чи «скільки влізе» — порушення.","Одне сидіння — один пасажир. Скільки місць, стільки й людей."],
"k2":["Водій маршрутки чи автобуса під час рейсу не розмовляє з пасажирами, не їсть, не п’є і не палить — уся його увага має бути на дорозі.","За кермом маршрутки — ні балачок, ні перекусів, ні цигарок."],
"k3":["Якщо кабіна водія маршрутки відгороджена від салону, туди не можна садити пасажирів і класти вантаж — навіть коли в салоні тісно.","Кабіна водія — тільки для водія: ні пасажирів, ні сумок."],
"k4":["Перед поїздкою дітям і дорослим-супровідникам пояснюють, як поводитися в дорозі й що робити, якщо станеться аварія. Без такого інструктажу групу не везуть.","Спочатку інструктаж — потім посадка: діти знають, як поводитися й що робити в разі біди."],
"k5":["Організовану групу дітей може везти лише досвідчений водій автобуса: зі стажем щонайменше 5 років і з посвідченням категорії D.","D — як «діти»: категорія D і щонайменше 5 років стажу."],
"k6":["Коли діти сідають в автобус зі знаком «Діти» чи виходять з нього, вмикають оранжеві маячки та/або аварійку. Так інші водії розуміють, що поруч можуть бути діти.","Діти виходять — блимають оранжеві маячки чи аварійка: увага, малеча!"],
"k7":["Двері автобуса чи маршрутки відчиняють лише тоді, коли транспорт повністю зупинився. А рушати можна тільки після того, як двері повністю зачинилися.","Спершу стоп — потім двері. Спершу двері — потім рух."],
"k8":["Везти до 8 людей у пристосованій вантажівці може водій із категорією C і стажем понад 3 роки. Якщо людей більше 8 — потрібні категорії C і D.","Люди в кузові — це C плюс досвід: понад 3 роки стажу."],
"k9":["Сидіння в кузові вантажівки кріплять на висоті 0,3–0,5 м від підлоги й щонайменше на 0,3 м нижче верхнього краю борту, щоб борт захищав людей.","0,3–0,5 м від підлоги: сидіння низько, борт високо."],
"k10":["У кузові звичайної вантажівки можуть їхати лише ті, хто супроводжує вантаж або їде по нього, і тільки якщо в них є місця для сидіння. Сторонніх туди не садять.","Кузов — не автобус: їде лише той, хто при вантажі, і тільки сидячи."],
"k11":["Перш ніж рушати з людьми в кузові, водій пояснює їм, як сідати й виходити, де розміщуватися і як поводитися під час поїздки.","Людей у кузові спершу інструктують, а потім везуть."],
"k12":["У причепі-дачі (житловому причепі) возити людей заборонено — він не призначений для пасажирів у дорозі. Їхати можна в автобусі чи пасажирському фургоні.","Причіп-дача — щоб жити на стоянці, а не щоб їхати в ньому."],
"k13":["Дитину нижчу за 150 см на задньому сидінні мотоцикла чи мопеда возити не можна. 130 см — замало, і шолом цього не змінює.","Менше 150 см — на мотоцикл позаду не сідає."],
"k14":["В автобусі, що возить пасажирів і тримається обмежень швидкості, дитяче крісло не обов’язкове. А в таксі чи звичайному легковику дитині нижчій за 150 см воно потрібне.","Автобус — виняток: там дитина їде без крісла. Таксі — не виняток."],
"k15":["До 16 років у кузові будь-якої вантажівки їздити не можна, навіть якщо там є сидіння зі спинками чи поруч дорослий. 15 років — ще замало.","Кузов вантажівки — зона 16+."],
"k16":["Організовані групи дітей не можна везти в темну пору доби. Уночі гірша видимість і ризик більший, тож такі поїздки планують на світлий час.","Діти їдуть удень: темрява — не для дитячих автобусів."],
"k17":["Дитяче крісло зазвичай ставлять не в першому ряду. Виняток — малюк до 3 років у кріслі, повернутому проти руху, і лише з вимкненою фронтальною подушкою безпеки.","Спереду — лише малюк до 3 років: обличчям назад, подушка вимкнена."],
"k18":["Автокрісло підбирають не за віком і не за машиною, а за тим, скільки дитина важить і який у неї зріст.","Крісло підбирають по дитині, а не по паспорту: вага й зріст."],
"k19":["Скільки вантажу можна взяти, визначає технічна характеристика авто: вона обмежує і загальну масу, і навантаження на кожну вісь. Великий кузов чи потужний мотор цього не змінюють.","Межу ваги пише виробник, а не розмір багажника."],
"k20":["Розташування й кріплення вантажу перевіряєш перед виїздом і стежиш за ним дорогою, щоб нічого не впало, не волочилося й нікого не травмувало.","Перед стартом — перевір, у дорозі — пильнуй."],
"k21":["Дошки на даху треба закріпити так, щоб авто залишалося стійким і керованим, а вантаж не закривав тобі огляд. Тент тут ні до чого.","Вантаж на даху: машина не хитається, огляд не закритий."],
"k22":["Вантаж, зокрема велосипеди на кріпленні ззаду, не має закривати ліхтарі, світлоповертачі й номер. Інакше тебе гірше видно, а номер не прочитати — і вдень теж.","Ліхтарі й номер завжди на виду — велосипед їх не ховає."],
"k23":["Вантаж не повинен пилити й засмічувати дорогу. Якщо пісок здуває з кузова, ти порушуєш саме цю вимогу, навіть коли маса в нормі.","Що в кузові — те не на дорозі: пісок не має летіти на інших."],
"k24":["Якщо вантаж виступає ззаду більш як на 1 м, його кінець позначають знаком «Негабаритний вантаж». 1,5 м — це вже більше, тож позначка потрібна.","Стирчить понад метр — повісь «Негабаритний вантаж» на кінці."],
"k25":["Вантаж, що стирчить убік, позначають, коли він виходить за зовнішній край габаритного ліхтаря більш як на 0,4 м. Менший виступ позначати не треба.","Вбік стирчить понад 0,4 м від габарита — став позначку."],
"k26":["Вдень такий вантаж позначають квадратними щитками чи прапорцями 400×400 мм з червоно-білими діагональними смугами. Будь-яка ганчірка не підходить.","Червоно-біла «зебра» 400 на 400 мм — знак, що вантаж виходить за габарит."],
"k27":["У темряві негабаритний вантаж спереду позначають білими, ззаду червоними, а збоку оранжевими світлоповертачами чи ліхтарями.","Як в авто: спереду біле, ззаду червоне, збоку оранжеве."],
"k28":["Виступ ззаду до 2 м — ще звичайне перевезення (понад 1 м вантаж лише позначають). Якщо більше ніж 2 м, діють окремі правила для великогабаритних ТЗ.","1 м — познач, 2 м — межа: далі вже великогабарит."],
"h1":["Після купівлі авто маєш 10 діб, щоб його зареєструвати. Той самий строк діє після розмитнення чи переобладнання.","Нове авто — 10 діб на реєстрацію: стільки, скільки пальців на руках."],
"h2":["Переносити номер загалом не можна, але є виняток: якщо багажник на фаркопі його закриває, задній номер можна закріпити прямо на цьому багажнику.","Багажник закрив номер — номер переїжджає на багажник."],
"h3":["Номер має бути чистим, добре освітленим і без жодних наклейок чи доповнень, щоб його легко було прочитати будь-коли, а не лише на техогляді.","Номер — як паспорт авто: чистий, видимий і без «прикрас»."],
"h4":["Знак «Шипи» — білий трикутник із червоною каймою і літерою «Ш» — розміщують ззаду авто з шипованими шинами, щоб його бачили ті, хто їде позаду.","«Шипи» ззаду — бо попереджають тих, хто їде слідом."],
"h5":["Знак навчального авто — білий трикутник вершиною догори з червоною каймою і літерою «Н». Його ставлять спереду і ззаду.","«Н» — навчання: білий трикутник з червоною каймою, як у «Шипів», тільки літера інша."],
"h6":["Знак «Обмеження максимальної швидкості» розміщують ззаду ліворуч. Його ставлять і водії зі стажем менше 2 років, щоб інші бачили обмеження.","Обмеження швидкості — ззаду зліва, там, звідки тебе обганяють."],
"h7":["Синій квадратний знак «Водій, який перевозить дітей віком до трьох років» розміщують і спереду, і ззаду авто, щоб його помітили всі навколо.","Малюк у салоні — знак з обох боків: і спереду, і ззаду."],
"h8":["Цей знак можуть ставити водії з інвалідністю, а також ті, хто возить пасажирів з інвалідністю. Пільги на паркування самі по собі права на нього не дають.","Знак — за людиною з інвалідністю: за кермом вона чи в салоні."],
"h9":["Розпізнавальні знаки кріплять на висоті від 400 до 1600 мм від дороги — так їх добре видно іншим, і вони не заважають огляду.","Розпізнавальний знак — від 400 до 1600 мм над дорогою, ні нижче, ні вище."],
"h10":["З 40 км/год на рівній сухій дорозі легковик має зупинитися не далі ніж за 14,7 м. Перевищувати норму до 10% можна лише авто, випущеним до 1988 року, а твоє — 2015-го.","З 40 до нуля — за 14,7 м, тобто трохи менше за півтора десятка метрів."],
"h11":["Якщо з гальмівної системи тече рідина, гальма можуть відмовити будь-якої миті. Тому з такою несправністю їздити заборонено, навіть коли рівень поки в нормі.","Тече гальмівна рідина — гальма «стікають» разом з нею. Не їдь."],
"h12":["Стоянкове гальмо (ручник) має втримати легковик без вантажу на ухилі щонайменше 23%. Норма 16% — для авто з повним навантаженням, а 31% — для вантажівок без вантажу.","Легковик — 23%: між 16 для завантажених і 31 для вантажівок."],
"h13":["У легковика, модель якого ще випускають, кермо може мати вільний хід (люфт) не більше 10°. До 25° допускається лише для авто, знятих з виробництва.","Люфт керма — до 10°: трохи «погуляти» можна, але не більше десятка градусів."],
"h14":["Якщо підсилювач керма передбачений конструкцією, а він зламався, їздити не можна: кермо стає важким, і в критичну мить можна не встигнути повернути.","Зламаний підсилювач — кермо «залізне». Таке авто в рейс не йде."],
"h15":["Якщо ліва фара не світить ближнім, зустрічні водії можуть прийняти твоє авто за мотоцикл і неправильно оцінити його ширину. Тому з такою несправністю їздити заборонено.","Ліва фара — та, що ближче до зустрічних: без неї ти для них «мотоцикл»."],
"h16":["На легковик можна додатково поставити дві протитуманні фари. Мотоцикл має право лише на одну, а легковик та інші ТЗ — на дві.","Скільки «очей» у машини, стільки й протитуманок — дві."],
"h17":["Склоомивач, передбачений конструкцією, має працювати так само, як і склоочисники. Без нього бруд зі скла не змити, тож їздити з такою несправністю заборонено.","Двірники без омивача лише розмазують бруд — потрібні обидва."],
"h18":["Протектор шин легковика не можна стирати глибше ніж до 1,6 мм. Якщо менше — шина гірше тримає дорогу, і їздити на ній заборонено.","Драбинка: вантажівка понад 3,5 т — 1,0, легковик — 1,6, автобус — 2,0 мм."],
"h19":["Для мотоциклів і мопедів межа зносу протектора — 0,8 мм. Якщо малюнок ще менший, їздити на такій шині заборонено.","Два колеса — і норма вдвічі менша: 0,8 мм проти 1,6 у легковика."],
"h20":["Шини причепа мають ту саму межу зносу протектора, що й шини авто, яке його тягне. Для причепа до легковика — 1,6 мм.","Причіп — як тягач: у легковика 1,6 мм, у його причепа — так само."],
"h21":["Якщо через поріз на шині видно корд, вона може будь-якої миті лопнути. З такими пошкодженнями їздити заборонено, хоч би який був тиск.","Видно корд — шина «показала скелет»: їздити не можна."],
"h22":["На одній осі не можна змішувати шиповану й нешиповану шини: вони по-різному тримають дорогу, і під час гальмування авто може повести вбік.","Одна вісь — пара близнюків: шипи або з обох боків, або ніде."],
"h23":["Радіальні й діагональні шини по-різному тримають дорогу, тому так їх поєднувати не можна: радіальні спереду, а діагональні на іншій осі — заборонено.","Радіальні спереду + діагональні ззаду = заборона."],
"h24":["Якщо з паливної системи підтікає паливо, авто може загорітися. Тому з такою несправністю їздити заборонено, навіть коли тече зовсім трохи.","Де капає пальне, там чекай вогню: з таким витоком авто не їде."],
"h25":["Звуковий сигнал потрібен, щоб попередити про небезпеку. Якщо він не працює, їздити заборонено — аварійка його не замінює.","Авто «оніміло» — у рейс не йде."],
"h26":["Тонування дозволене, якщо скло пропускає достатньо світла за стандартом. А дзеркальне скло не дозволене, навіть від виробника.","Тонування за стандартом — так, дзеркало — ні."],
"h27":["Щоб легковик міг виїхати на дорогу, у ньому мають бути аптечка, знак аварійної зупинки і працездатний вогнегасник. Саме ця трійка обов’язкова.","Лікувати, попереджати, гасити: аптечка, знак, вогнегасник."],
"h28":["Якщо сигнал зламався в дорозі й полагодити його не виходить, можна їхати, але найкоротшим шляхом до стоянки чи ремонту, обережно й з аварійкою.","Сигнал «онімів» у дорозі — не в гості, а найкоротшим шляхом до ремонту."],
"h29":["У дощ без склоочисника з боку водія ти майже нічого не бачиш. Тому їхати далі не можна взагалі — навіть до ремонту.","Дощ і мертвий двірник перед тобою — стоп. Навіть до СТО не їдеш."],
"h30":["Уночі без фар ти не бачиш дороги, а тебе погано бачать інші. Тому їхати далі заборонено, навіть з аварійкою чи габаритами.","Ніч і фари згасли — далі ні метра."],
"f1":["Якщо на дорогу вискочила тварина, гальмуй, тримаючи кермо рівно, щоб за потреби зупинитися. Різкий маневр на швидкості легко закінчується кюветом або зустрічною смугою.","Звір на дорозі: гальмо — так, різке кермо — ні."],
"f2":["Коли задок авто заносить, плавно повертай кермо в той бік, куди його несе. Так машина вирівнюється.","Куди несе зад — туди й кермо, але плавно."],
"f3":["Коли авто «пливе» по воді, шини втратили контакт з дорогою. Плавно відпусти газ, не гальмуй різко й не крути кермо — так зчеплення повернеться.","На воді — як на льоду: жодних різких рухів, просто відпусти газ."],
"f4":["На мокрій дорозі гальмувати доводиться довше, а на льоду гальмівний шлях зростає в рази. Тому на слизькому знижуй швидкість і тримай більшу дистанцію.","Мокро — довше, лід — у рази довше."],
"f5":["Номер 112 — єдиний для всіх екстрених служб: рятувальників, поліції та швидкої. Окремо можна дзвонити 101, 102 і 103.","112 — один номер на всі біди: і пожежа, і поліція, і швидка."],
"f6":["Якщо людина непритомна, але дихає, поклади її на бік у стабільне положення: так дихальні шляхи лишаються вільними. І весь час стеж за диханням.","Дихає, але не реагує — на бік, щоб нічого не перекрило дихання."],
"f7":["Під час реанімації дорослого роби 30 натискань на грудну клітку, потім 2 вдихи, і так по колу. Натискай у центр грудей з частотою 100–120 на хвилину.","30:2 — тридцять разів тиснеш, двічі вдихаєш."],
"f8":["Коли кров б’є струменем, накладай джгут вище рани — між раною і серцем — і запиши час. Потім негайно викликай швидку.","Джгут — між раною і серцем, а час — запиши."],
"f9":["Перш ніж кидатися на допомогу, оглянься: чи не їдуть машини, чи немає вогню чи витоку пального. Якщо постраждаєш ти, допомагати вже не буде кому.","Спершу безпека — потім допомога: рятівник має бути цілим."],
"f10":["Замість знака аварійної зупинки можна поставити миготливий червоний ліхтар — він так само попереджає інших водіїв про зупинене авто.","Червоне миготіння = той самий знак аварійної зупинки, тільки світиться."],
"f11":["До приїзду поліції сліди аварії не прибирають: їх зберігають, огороджують і організовують об’їзд, щоб поліція могла з’ясувати, як усе сталося.","Сліди ДТП — як докази: не чіпай, огороди, організуй об’їзд."],
"f12":["Якщо ні надати допомогу, ні викликати швидку не виходить, звернися до людей поруч і відправ потерпілого до лікарні. Чекати склавши руки чи їхати геть не можна.","Не можеш допомогти — знайди тих, хто може, і відправ потерпілого до лікарів."],
"f13":["Дзвонячи на 112, назви місце, що сталося і скільки потерпілих. Слухавку не клади, доки диспетчер не завершить розмову: він може уточнити деталі й підказати, що робити.","Де? Що? Скільки? — і чекай, поки диспетчер попрощається."],
"f14":["Без потреби людину з авто не витягають: зайві рухи можуть погіршити травми, особливо хребта. Виймати треба, лише коли загрожує щось гірше, наприклад пожежа.","Горить — витягай. Нічого не загрожує — не руш."],
"f15":["Шолом без потреби не знімай: так легко пошкодити шию. Знімають його лише тоді, коли треба звільнити дихальні шляхи чи робити реанімацію.","Дихає — шолом на голові. Шия дорожча за цікавість."],
"f16":["Закинь людині голову, підніми підборіддя і до 10 секунд дивись, слухай і відчувай, чи дихає вона. Рідкі судомні вдихи — це не нормальне дихання.","Дивись, слухай, відчувай — не довше 10 секунд."],
"f17":["Якщо людина не реагує і не дихає нормально, викликай швидку (112 або 103) і одразу починай натискати на грудну клітку. Стабільне положення тут уже не допоможе.","Не дихає — не чекай: дзвінок і руки на груди."],
"f18":["Натискай на грудну клітку 100–120 разів на хвилину — це приблизно два натискання щосекунди. Після кожного давай грудям повністю розправитися.","Два натискання щосекунди — і ти якраз у темпі 100–120."],
"f19":["Під час реанімації дорослого груди продавлюють на 5–6 см, прямими руками й вагою тіла. Слабкі натискання не забезпечують кровообігу.","5–6 см: тиснути глибоко, всією вагою, а не легенькими поштовхами."],
"f20":["Руки кладуть посередині грудей, на нижню половину грудини: основа долоні внизу, друга долоня зверху, руки прямі. Не ліворуч над серцем і не на живіт.","Тисни по центру, а не зліва: серце стискають через грудину."],
"f21":["Реанімацію не обмежують хвилинами: продовжуй, доки не приїдуть медики, людина не почне нормально дихати або в тебе не скінчаться сили.","Три «стопи» для СЛР: медики, дихання або повне виснаження."],
"f22":["Дефібрилятор розрахований і на звичайних людей: увімкни його якомога швидше й роби те, що він підказує голосом. Під час аналізу й розряду ніхто не торкається потерпілого.","Дефібрилятор сам підказує: увімкни і слухайся."],
"f23":["Якщо кров тече рівно, без струменя, притисни рану чистою тканиною й наклади тиснучу пов’язку. Джгут потрібен лише для кровотеч, небезпечних для життя.","Тече — тисни. Б’є струменем — тоді вже джгут."],
"f24":["При кровотечі з носа людину садять, нахиляють їй голову вперед і притискають крила носа. Якщо закинути голову, кров стікатиме в горло.","Кров з носа — голову вперед, а не назад."],
"f25":["Уламок у рані не виймай: він може закривати пошкоджену судину, і без нього кров піде сильніше. Зафіксуй його пов’язкою навколо.","Застрягло — не тягни: уламок сам працює як пробка."],
"f26":["Опік охолоджуй прохолодною проточною водою, а потім накрий чистою пов’язкою. Олія тримає жар і загрожує інфекцією, а лід ще більше шкодить тканинам.","Опік — під воду, не в олію й не в лід."],
"f27":["Пухирі після опіку не проколюй і не зрізай — вони захищають рану від інфекції. Просто накрий місце чистою пов’язкою.","Пухир — природний пластир: не чіпай його."],
"f28":["Якщо підозрюєш перелом, не пробуй вправити кістку: зафіксуй ногу так, як вона лежить. Спроби вирівняти посилюють біль і можуть пошкодити судини та нерви.","Як лежить — так і фіксуй."],
"f29":["Біль у шиї після удару може означати травму хребта. Попроси людину не рухатися й обережно тримай її голову руками нерухомо.","Болить шия — голова «на замку» у твоїх руках."],
"f30":["Бліда холодна волога шкіра й частий пульс — ознаки шоку. Поклади людину, вкрий, щоб не мерзла, викликай швидку й не давай їсти чи пити.","Шок: лежати, тепло, швидка."],
"f31":["Зупиняючи чужу кровотечу, вдягай медичні рукавички з аптечки — вони захищають від інфекцій, що передаються через кров.","Чужа кров — тільки в рукавичках."],
"f32":["Якщо людина не може ні кашляти, ні говорити, ні дихати, зроби до 5 ударів між лопатками, а потім до 5 поштовхів у живіт. Вода тут не допоможе.","Спершу спина, потім живіт: до 5 ударів і до 5 поштовхів."],
"f33":["Під час удару непристебнутий пасажир ззаду летить уперед з величезною силою і травмує не лише себе, а й тих, хто сидить попереду. Ремінь ззаду захищає всіх.","Непристебнутий позаду — живий снаряд для тих, хто спереду."],
"f34":["Подушка безпеки працює лише разом із ременем. Без ременя тіло летить на подушку саме тоді, коли вона розкривається, і можна дістати тяжкі травми.","Подушка — помічник ременя, а не його заміна."],
"f35":["Перевантажене авто довше гальмує і гірше слухається керма, бо зайва вага перевантажує гальма, шини й підвіску.","Важча машина — довше гальмує і ліниво кермується."],
"f36":["Верх підголовника має бути приблизно на рівні верхівки голови. Тоді під час удару ззаду він підхопить голову й захистить шию.","Підголовник — урівень з маківкою, а не з шиєю."],
"f37":["Плечова лямка ременя має йти через середину ключиці й груди — не по шиї і не під пахвою. А поясна — низько на стегнах, не на животі.","Ремінь — через ключицю, не через шию."],
"f38":["Вагітній теж треба пристібатися: поясна лямка йде під животом, а плечова — між грудьми й збоку від живота. Так ремінь утримує тіло, не тиснучи на живіт.","Живіт — в обхід: одна лямка під ним, друга — збоку."],
"f39":["Фронтальна подушка розкривається з величезною силою і б’є прямо в крісло, повернуте проти руху. Тому таке крісло спереду ставлять лише з вимкненою подушкою.","Крісло проти руху + увімкнена подушка = удар по дитині."],
"f40":["Об’ємна куртка стискається під лямками, і між ними та тілом лишається слабина — під час удару дитина може вислизнути. Краще зняти куртку й накрити нею дитину поверх лямок.","Лямки — до тіла, куртка — зверху."],
"f41":["У спеку салон зачиненого авто нагрівається до небезпечної температури за лічені хвилини, навіть із прочиненим вікном. Дитину не можна лишати там ні на хвилинку.","Машина на сонці — як духовка: навіть «на хвилинку» — ні."],
"f42":["У далекій дорозі зупиняйся приблизно кожні 2 години. А якщо позіхаєш, повіки важчають чи пропускаєш знаки — зупиняйся одразу.","Кожні 2 години — перерва, а позіхається — зупинка зараз."],
"f43":["Кава чи холодний душ лише дають відчуття бадьорості, а алкоголь з організму нікуди не дівається. Протверезити може тільки час.","Від алкоголю рятує годинник, а не кавоварка."],
"f44":["Мости й естакади охолоджуються з усіх боків, а в тіні лід не тане, тож ожеледь там з’являється раніше. Перед ними заздалегідь знижуй швидкість.","Міст мерзне і знизу, і зверху, тінь не гріє — там лід з’являється першим."],
"f45":["З ABS тисни на гальмо сильно й до упору й не відпускай — система не дасть колесам заблокуватися, і кермо слухатиметься. Вібрація педалі — це нормально.","З ABS — «у підлогу» і тримай, а кермом — в об’їзд."],
"f46":["Заблоковані колеса ковзають, і авто перестає слухатися керма. Переривчасте гальмування не дає колесам заблокуватися, тож можна і гальмувати, і кермувати.","Без ABS — будь своєю ABS: тисни й відпускай."],
"f47":["Гальмівний шлях росте пропорційно квадрату швидкості: удвічі швидше — приблизно в 4 рази довше. Тож з 100 км/год гальмуєш учетверо довше, ніж з 50.","Удвічі швидше — учетверо довше: швидкість гальмує «в квадраті»."],
"f48":["Коли розірвало колесо, міцно тримай кермо, плавно відпусти газ і гальмуй м’яко. Різке гальмування чи ривок кермом легко зривають авто в занос.","Лопнуло колесо — міцні руки, м’яка нога."],
"f49":["72 км/год — це 20 метрів щосекунди. Відвівши погляд на 2 секунди, ти проїжджаєш наосліп близько 40 м — довжину кількох автобусів.","Погляд у телефон на 2 секунди — 40 метрів дороги без водія."],
"f50":["Чим швидше їдеш і чим менше лишилося протектора, тим гірше шина відводить воду — і авто «спливає». Повільніше й з добрими шинами ризик менший.","Швидко + лиса шина = водні лижі."],
"f51":["У тумані дальнє світло відбивається від крапель і повертається тобі в очі світлою «стіною». Краще ближнє й протитуманні фари.","Дальнє в тумані — як ліхтарик у дзеркало: світить тобі ж в очі."],
"f52":["Коли зустрічні фари сліплять, переведи погляд на правий край дороги — так ти не дивишся у світло й тримаєш напрямок.","Яскраво зліва — погляд праворуч, на край дороги."],
"f53":["Дим з-під капота — сигнал можливої пожежі. Зупинись, заглуши двигун, виведи всіх з авто й викликай рятувальників. Капот повністю не відчиняй — повітря роздмухає вогонь.","Дим — стоп, мотор вимкнути, люди назовні, дзвінок 101 чи 112."],
"f54":["Гасити треба те, що горить, а не полум’я над ним, тому струмінь вогнегасника спрямовуй на основу вогню. І стань так, щоб вітер дув тобі в спину.","Бий по корінню вогню, а не по верхівках."],
"f55":["Під час різкого гальмування чи удару незакріплені речі летять уперед з силою, у десятки разів більшою за їхню вагу, і травмують людей. Важке клади в багажник.","Сумка на полиці при ударі — снаряд у потилицю."]
};
